"""Original V15 lock/salinity lessons; source facts and synthetic arithmetic are separated."""
from pathlib import Path
import json,re,hashlib,math
H=Path(__file__).resolve().parent
TARGETS={t['id']:t for t in json.loads((H/'targets.json').read_text())}
S={};D={};META={}
def pair(z,e):return z+'~'+e
def source(key,z,en,publisher,url,scope,scopeEn,evidence):
 S[key]=dict(key=key,title=z,titleEn=en,publisher=publisher,url=url,sourceType='primary',scope=scope,scopeEn=scopeEn,evidence=evidence,accessed='2026-10-21')
def compact(cid,focus,rows):
 units=[]
 for row in rows.strip().splitlines():
  if not row.strip():continue
  title,cause,model,verify,failure,mis=[x.strip()for x in row.split(' || ')]
  cz,ce=cause.split('~');mz,me=model.split('~')
  units.append(dict(anchor=title,title=title,mechanism=pair(cz+' '+mz,ce+' '+me),model=pair('原創教學假設，非操作設定。'+mz,'Original teaching assumptions, not operating settings. '+me),verify=verify,practice=verify,failure=failure,misconception=mis))
 assert len(units)==10
 D[cid]=dict(id=cid,focus=focus,units=units)
def generate():
 for cid,d in D.items():
  t=TARGETS[cid];m=META[cid];u=d['units']
  facts=[x['model']for x in u if len(re.findall('[㐀-鿿]',x['model'].split('~')[0]))<=90 and len(re.findall('[A-Za-z]{2,}',x['model'].split('~')[1]))<=45][:6]
  assert len(facts)==6,(cid,len(facts))
  vendors=[]
  for k in m['vendorSources']:
   s=S[k];vendors.append(dict(name=s['publisher'],nameEn=s['publisher'],business='發布相關水利方法、研究或公共工程資訊。',businessEn='Publishes relevant water-engineering methods, research or public project information.',url=s['url'],investorUrl='',security=None,role=s['scope'],roleEn=s['scopeEn']))
  d.update(title=t['title']+'~'+t['titleEn'],discipline=t['discipline'],family='water',summary=m['summary'],history=m['history'],example=m['example'],facts=facts,timeline=[dict(year=y,event=e)for y,e in m['timeline']],codes=m['codes'],landmarks=m['landmarks'],place=m['place'],sources=[{k:v for k,v in S[s].items()if k not in ('evidence','accessed')}for s in m['sources']],vendors=vendors,related=m['related'],architectureNodes=[x['title'].split('~')for x in (u[0],u[2],u[4],u[7],u[9])],architectureEdges=[[0,1],[1,2],[2,3],[3,4],[4,1]])
  (H/'inputs'/f'{cid}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 (H/'locks_coast_extra_research.json').write_text(json.dumps(dict(accessed='2026-10-21',sources=S,courses={k:v['sources']for k,v in META.items()},limits=['Numerical models are declared original synthetic assumptions, not project field values.','Official indexed excerpts are identified separately from directly opened sources.','No source endorsement or investment/security listing is claimed.']),ensure_ascii=False,indent=2)+'\n')
 print('Generated',list(D))
source('dam-dynamics','混凝土水工結構歷時動力分析','Time-History Dynamic Analysis of Concrete Hydraulic Structures EM1110-2-6051','US Army Corps of Engineers','https://www.publications.usace.army.mil/Portals/76/Publications/EngineerManuals/EM_1110-2-6051.pdf','官方目錄確認二〇〇三年十二月線彈性歷時分析手冊；不將線性模型外推為開裂、滑動或土壩液化驗證。','Official catalogue confirms December2003 linear-elastic time-history guidance; it does not validate cracking, sliding or embankment liquefaction by linear extrapolation.','Official indexed turn214search1 and turn214search47, date December22,2003.')
source('embankment-seismic','土石壩耐震分析與設計','Design Standards No.13 Chapter13: Seismic Analysis and Design','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/designstandards-datacollectionguides/finalds-pdfs/DS13-13.pdf','官方清單列二〇一五年五月土石壩耐震章節；材料非線性和震後穩定與混凝土線性振子分開解讀。','Official list dates the embankment seismic chapter to May2015; material nonlinearity and post-earthquake stability are distinguished from a linear concrete oscillator.','Official indexed turn214search0 and turn214search46 confirm scope and date.')
source('hoover-history','胡佛壩建設歷程','Hoover Dam construction history','US Bureau of Reclamation','https://www.usbr.gov/history/hoover.html','官方歷史記錄混凝土壩、鋼管與錨定工程；本課僅作結構型式比較，不將合成動力參數宣稱為胡佛壩資料。','Official history describes the concrete dam, penstocks and anchorage; used for structural-type comparison, not as the source of synthetic dynamic parameters.','Official indexed turn218search0 and turn214search39;1935 last main-dam concrete,1936 works and initial generation.')
source('sisk-history','聖路易水庫西斯克壩背景','B.F. Sisk Dam history and modification context','US Bureau of Reclamation','https://usbr.gov/newsroom/news-release/4469?field_story=1&field_story_archive=Safety+of+Dams&topic=Safety+of+Dams','官方記錄一九六三至一九六七年土石壩建設；僅與混凝土壩比較材料機制，不宣稱本課振子重現場址。','Official account records1963–1967 earthfill-dam construction; comparison concerns material mechanisms, not reproduction of the site by a single oscillator.','Official indexed turn218search17 confirms dates and zoned earthfill type.')
compact('b256','從模態質量與輸入歷時辨識水壩動力分析的假設界限~Identify dam-dynamics assumptions through modal mass, forcing histories and model boundaries',r'''
模態質量與週期~Modal mass and period || 水壩地震反應不是把整座重量直接乘一個係數，首先要理解材料剛度、基礎與水庫如何形成振動模態。單自由度模型只代表已選定的廣義座標，其質量和剛度必須成對校準；不同模態參與程度不同，第一週期吻合也不能證明全部壩體應力分布正確。~Dam response begins with how stiffness, foundation and reservoir interactions form vibration modes rather than multiplying total weight by one coefficient. A single degree of freedom represents a chosen generalized coordinate whose mass and stiffness must be calibrated together. Matching the first period does not establish the correctness of higher modes or the complete spatial stress distribution. || 假設線性模態質量m=50000000kg、剛度k=2000000000N/m，ω=√(k/m)=6.325rad/s，T=2π/ω=0.9935s。~Assume linear modal mass50000000kg and stiffness2000000000N/m. ω=√(k/m)=6.325rad/s and T=2π/ω=0.9935s, for this generalized coordinate only. || 在自由體圖上說明廣義座標與質量正規化，核對剛度及質量是否使用同一模態定義。將解析週期與有限元素特徵值及環境振動資料比較，保留水位和溫度條件，不只調整一個參數湊合。~Define the generalized coordinate and mass normalization and check consistent stiffness and mass conventions. Compare the analytical period with eigenvalue and ambient-vibration evidence while retaining water-level and temperature conditions rather than tuning one parameter merely to force agreement. || 模態質量誤用總壩重會讓週期和慣性力同時錯位，固定基礎假設也可能高估剛度。第一週期接近量測時，局部接縫、壩肩或高階反應仍可能沒有被描述。~Using total dam mass as modal mass distorts both period and inertia, while an unrealistically fixed foundation may overstate stiffness. A matching first period can still leave joints, abutments and higher-mode responses poorly represented. || 第一振動週期吻合即可證明整座水壩的地震應力全部正確。~Matching the first natural period proves that every earthquake stress in the dam is correct.
慣性力與加速度~Inertia and acceleration definition || 慣性力跟質量及相應的絕對加速度有關，但地表峰值、基岩輸入與結構反應不是同一數據。等效靜力只提供量級，不能代替時變相位與變形計算；三方向輸入還要保持坐標一致，避免把不同時刻峰值任意拼成實際不存在的受力狀態。~Inertia depends on mass and its corresponding absolute acceleration, but surface peak, bedrock input and structural response are different quantities. Equivalent static force gives a scale rather than temporal phase or deformation. Three-component inputs also require consistent coordinates, and unrelated peaks must not be assembled into a force state that never occurred in the actual time history. || 假設所選質量50000000kg瞬時絕對加速度0.20g，F=ma=98.10MN；此數值不是由地表PGA自動得到的壩體反應。~Assume selected mass50000000kg has instantaneous absolute acceleration0.20g. F=ma=98.10MN, not a dam response automatically inferred from surface PGA. || 分欄記錄輸入點、反應點、單位及坐標方向，確認g已乘9.81m/s²。以同時刻的加速度與支承反力檢查動力平衡，並區分絕對和相對加速度，不拿不相干峰值作平衡驗算。~Record input and response locations, units and axes separately, converting g to9.81m/s². Check dynamic balance using simultaneous accelerations and support reactions and distinguish absolute from relative acceleration instead of combining unrelated individual peak values for equilibrium. || 把相對加速度當成絕對值可能漏掉地盤運動，三方向最大值不同時發生又會製造過大合力。反之僅用輸入PGA代表結構加速度，可能漏掉共振放大。~Treating relative acceleration as absolute omits ground motion, while asynchronous directional peaks can create an excessive resultant. Conversely, using input PGA for structural acceleration can miss amplification caused by resonant response of the selected mode. || 地表峰值加速度就是壩體每一點在同一時刻的絕對加速度。~Surface peak acceleration equals the simultaneous absolute acceleration at every point of the dam.
阻尼係數與耗能~Damping coefficient and dissipation || 阻尼比是相對臨界阻尼的比例，實體耗能可包含材料、接縫和基礎輻射，不應任意重複加入。線性黏滯模型便於分析但不能代表所有開裂摩擦機制，且校準模態與頻率範圍必須明示；增加阻尼使數值變小不等於取得可靠設計。~Damping ratio is relative to critical damping, while physical dissipation can include material, joints and radiation into the foundation. These effects must not be counted twice. Linear viscous damping is convenient but does not represent every cracking or friction mechanism, and calibration needs a specified modal and frequency range rather than an arbitrary value chosen to reduce response. || 假設m=50000000kg、k=2000000000N/m、ζ=0.05，c=2ζ√(km)=31622776.6N·s/m；只代表線性黏滯阻尼。~Assume m=50000000kg,k=2000000000N/m and ζ=0.05. c=2ζ√(km)=31622776.6N·s/m, representing linear viscous damping only. || 列出材料阻尼、邊界吸收和接觸摩擦的實作位置，檢查同一耗能是否重複計算。以自由衰減或頻率反應資料校核，另做阻尼敏感度，保存反應改變原因而非只報最小應力。~Map material damping, absorbing boundaries and contact friction to check duplicate dissipation. Compare free-decay or frequency-response evidence and perform damping sensitivity, explaining changed response rather than reporting only the smallest calculated stress from a favorable parameter choice. || 同時採很大材料阻尼和強吸收邊界可能過度消能，掩蓋壩肩需求。把小振幅試驗阻尼直接外推到嚴重開裂狀態，也會忽略隨振幅改變的機制。~Large material damping combined with strongly absorbing boundaries can remove excessive energy and hide abutment demand. Extending small-amplitude damping into severe cracking also overlooks mechanisms that change as deformation amplitude grows during shaking. || 阻尼設得越大就一定越接近真實水壩的地震反應。~A larger damping value always makes the predicted dam earthquake response more realistic.
諧波放大與歷時~Harmonic magnification versus history || 共振概念可用持續正弦力說明，但地震是有限時間且頻率不斷改變的訊號，兩者反應不能混用。線性振子的穩態放大取決於頻率比及阻尼，建立穩態需要時間；脈衝、非線性接縫和頻率漂移可能使真正峰值與簡式大不相同。~Sustained sinusoidal force illustrates resonance, but earthquakes have finite duration and changing frequency content. Their responses are not interchangeable. Steady harmonic amplification depends on frequency ratio and damping and takes time to develop. Pulses, nonlinear joints and frequency shifts can make actual peaks substantially different from the simplified forced-oscillator value even when its natural period is known. || 假設線性受迫穩態、頻率比r=1、ζ=0.05，R=1/√[(1−r²)²+(2ζr)²]=10；非地震歷時放大保證。~Assume linear steady forced response with frequency ratio r=1 and ζ=0.05. R=1/√[(1−r²)²+(2ζr)²]=10, not an earthquake amplification guarantee. || 畫出多個頻率比的反應曲線，標明以靜態位移為分母的定義。再輸入短脈衝與有限週期正弦比較建立時間，檢查模型仍線性時兩種結果為何不同，不把穩態峰值直接當地震需求。~Plot response over several frequency ratios and state that magnification is relative to static displacement. Compare a short pulse and finite-cycle sinusoid to show buildup time, explaining their differences within the linear model rather than directly using the steady peak as earthquake demand. || 地震短脈衝未必有時間建立穩態，直接套十倍可能高估；若忽略結構頻率變化或其他模態，也可能漏掉另一時間段的放大。單一數值無法替代完整歷時檢查。~A short pulse may not build steady resonance, making direct tenfold scaling excessive. Ignoring frequency change or additional modes can instead miss amplification later in the record, so one factor cannot replace evaluation of the full time history. || 共振穩態放大係數可直接乘所有地震峰值作為真實反應。~The steady resonant magnification can directly multiply every earthquake peak to give the actual response.
反應譜位移換算~Spectral displacement conversion || 擬加速度反應譜與位移譜在同一線性振子和阻尼下可由角頻率換算，但擬加速度不是任意量測絕對加速度峰值。譜值忽略不同模態峰值發生時間，合成規則需另外選擇；先確認譜的定義與單位，才有資格比較位移和接縫需求。~Pseudo-spectral acceleration and spectral displacement convert through angular frequency for the same linear oscillator and damping. Pseudo-acceleration is not an arbitrary measured absolute-acceleration peak. Spectra also omit the timing of different modal maxima, requiring separate combination rules. Definitions and units must therefore be checked before comparing converted displacement with joint or deformation demands. || 假設同一線性振子週期T=1s、擬譜加速度Sa=0.40g，Sd=Sa/(2π/T)²=0.09940m；阻尼定義保持一致。~Assume the same linear oscillator has T=1s and pseudo-spectral acceleration Sa=0.40g. Sd=Sa/(2π/T)²=0.09940m at consistently defined damping. || 核對輸入是擬譜加速度或絕對加速度譜，將g與角頻率的轉換逐步寫出。用同一歷時振子直接求位移峰值對照，確認週期及阻尼一致，並保留多模態合成方法的另行說明。~Identify pseudo-spectral versus absolute-acceleration input and show conversion from g and period to angular frequency. Compare with direct oscillator displacement from the same record at matching period and damping, documenting the separate method used for multiple-mode combination. || 將Hz直接當rad/s會使位移差數十倍，不同阻尼譜混用又會改變需求。即使單模態位移正確，各模態峰值同號相加仍可能不代表任何真實時刻。~Using hertz as radians per second changes displacement by a large factor, and mixing damping definitions changes demand. Even correct individual modal displacements need not occur with equal signs at one actual instant. || 任何加速度峰值除以頻率平方都一定得到正確的反應譜位移。~Any acceleration peak divided by frequency squared necessarily gives the correct spectral displacement.
瑞利阻尼頻帶~Rayleigh damping frequency band || 質量與剛度比例阻尼可在兩個指定模態匹配目標，但頻帶之外不會維持同一比例。低頻受質量項控制、高頻受剛度項控制，網格細化加入高頻模態可能造成過度衰減；應檢查整段頻率曲線，不能只驗算兩個校準點就認為全部動力都一致。~Mass- and stiffness-proportional damping can match a target at two selected modes but does not maintain that ratio outside them. The mass term dominates low frequency and stiffness term high frequency, so refinement can add excessively damped modes. Examine the full curve instead of assuming that agreement at two calibration points establishes consistent damping throughout the dynamic model. || 假設兩模態1與3Hz均ζ=0.05，C=αM+βK得α=0.47124s⁻¹、β=0.0039789s；在2Hz時ζ=0.04375。~Assume target damping0.05 at1 and3Hz. C=αM+βK gives α=0.47124s⁻¹,β=0.0039789s; at2Hz the damping ratio is0.04375. || 在模型使用的最低到最高頻率畫阻尼曲線，標出兩個校準模態及中間值。網格改變後重新檢查新增高頻耗能，並確認剛度項採初始或更新剛度，避免非線性時含義悄悄改變。~Plot damping over the model’s relevant frequency range, marking calibration modes and intermediate values. Recheck high-frequency dissipation after mesh changes and identify whether the stiffness term uses initial or updated stiffness, preventing an unnoticed change of meaning in nonlinear calculations. || 高頻過度阻尼可能抹掉局部衝擊或接觸反應，低頻質量阻尼也可能對近剛體運動產生不合理耗能。只報兩點匹配，無法看出頻帶外的數值偏差。~Excessive high-frequency damping erases local impact or contact response, while low-frequency mass damping may dissipate near-rigid movement unrealistically. Reporting only two fitted points hides numerical behavior outside the calibration band of the model. || 瑞利阻尼只要在兩個頻率匹配就會在所有頻率保持同樣阻尼比。~Rayleigh damping fitted at two frequencies has the same damping ratio at every frequency.
附加水質量與週期~Added water mass and period || 水庫動壓可能與壩體運動耦合，簡化附加質量僅在已指定形狀與頻率條件下代表某種等效作用。不能把整個水庫重量直接加到壩上，亦不能忽略可壓縮性、邊界吸收或水位改變；本單元固定剛度，只檢查一個假設附加量如何改變週期。~Reservoir pressure can couple with dam movement, while an added-mass approximation represents an equivalent effect only under stated geometry and frequency conditions. The entire reservoir mass cannot be attached to the dam, nor can compressibility, absorption and water-level change always be ignored. This unit holds stiffness fixed to isolate the period effect of one assumed modal addition. || 假設原模態m=50000000kg、附加水質量20000000kg、k=2000000000N/m，T=2π√[(m+ma)/k]=1.1755s。~Assume modal mass50000000kg,added water mass20000000kg and unchanged stiffness2000000000N/m. T=2π√[(m+ma)/k]=1.1755s for this assumed approximation. || 明列附加質量的推導範圍與所代表模態，與流固耦合模型在多個水位下比較。檢查水庫邊界是否過近造成反射，保存原質量和附加量分項，不把週期延長全歸因於材料變軟。~State the added-mass derivation and represented mode and compare coupled calculations at several levels. Check artificial reflection from nearby reservoir boundaries, retaining structural and water contributions separately rather than attributing every period increase to softened dam material. || 直接加整個水庫質量會嚴重扭曲週期，人工反射又可能假造動壓峰值。僅因空庫與滿庫週期不同就判定結構劣化，會把正常流固互制當成損傷。~Attaching the entire reservoir mass grossly distorts period, and artificial reflections create spurious pressure peaks. Declaring deterioration solely from empty- versus full-reservoir period differences mistakes normal fluid-structure interaction for structural damage. || 水庫對水壩動力的作用就是把全部庫水重量加到壩體質量。~Reservoir interaction simply adds the mass of all stored water to the dam.
同步位移與接縫~Synchronized displacement and joints || 接縫張開由相鄰部位同一時刻的相對位移決定，而不是兩個獨立最大值相減或平方和。坐標方向和局部法向需先定義，剛體平移應在相減時消除；縫面接觸、止水材料與剪切交互作用則需另建模型，位移量本身不代表水密性。~Joint opening comes from simultaneous relative displacement, not subtraction or quadrature of unrelated extrema. Coordinate direction and local normal must be defined so common rigid translation cancels. Contact, waterstop response and combined shear require additional models; a displacement difference alone does not establish watertightness or allowable joint performance during an earthquake. || 假設同時刻沿接縫法向位移u1=12mm、u2=−8mm，相對張開u1−u2=20mm；不是各自峰值的非同步組合。~Assume simultaneous normal displacements u1=12mm and u2=−8mm. Relative opening is20mm, rather than a combination of nonconcurrent individual maxima. || 先把兩側位移轉到同一局部法向與時鐘，再逐時刻求差並找峰值。另列剪切滑移、接觸壓和止水變形，檢查剛體平移能否抵銷，保留真正控制時刻供受力與漏水判讀。~Transform both records to one local normal and synchronized clock, then difference each time step before locating the peak. Record shear, contact pressure and waterstop deformation separately, checking cancellation of rigid translation and retaining the actual controlling instant for interpretation. || 時鐘偏移會把原本同步移動變成假張開，法向反轉又可能讓共同平移加倍。只取單側峰值會錯過兩側反向運動，低估止水和接觸介面的真正需求。~Clock offsets make common movement appear as opening, and reversed normals can double rigid translation. A one-sided peak can miss opposing movements and understate the actual demand on waterstops and contact interfaces between neighboring blocks. || 接縫最大張開永遠等於兩側各自最大位移的平方和平方根。~Maximum joint opening always equals the root-sum-square of each side's individual peak displacement.
時間步與高頻解析~Timestep and high-frequency resolution || 動力積分步長要解析關心的短週期，但每週期點數只是起點，不是收斂證明。輸入記錄取樣、內插方法、積分演算法和非線性接觸都可能施加更嚴限制；縮小步長後應比較峰值、相位及能量，而不是只確認程式沒有發散或報錯。~A dynamic timestep must resolve relevant short periods, but points per cycle are only an initial check, not proof of convergence. Input sampling, interpolation, integration algorithm and nonlinear contact may impose stricter limits. Refinement should compare peaks, phase and energy rather than merely confirming that software completes without numerical divergence or reported errors. || 假設最短關注週期0.20s、積分步長0.005s，點數T/Δt=40；不能由此保證輸入頻寬或接觸反應已解析。~Assume the shortest relevant period0.20s and timestep0.005s. T/Δt=40points per cycle, without guaranteeing input bandwidth or resolved contact response. || 使用相同物理模型分別減半步長，對照位移峰值、加速度與能量殘差，另檢查原始輸入取樣率。不要以內插創造原記錄沒有的高頻證據，並把未收斂局部反應獨立標示。~Halve the timestep with unchanged physics and compare displacement peaks, acceleration and energy residuals while checking original input sampling. Interpolation cannot create missing high-frequency evidence; flag local responses that remain unconverged rather than hiding them in global averages. || 程式穩定仍可能有顯著相位誤差，粗步長也會漏掉短促接觸力。把稀疏輸入內插成密集資料看似解析度提高，實際卻沒有補回缺失的地震頻率內容。~A stable computation can retain serious phase error and miss brief contact forces. Interpolating sparse input into many samples looks more resolved but does not restore earthquake frequencies absent from the original measured record. || 動力程式成功跑完且每週期有足夠點數就不必再查收斂。~A completed dynamic run with many points per period never needs a convergence assessment.
土壩孔壓與有效應力~Embankment pore pressure and effective stress || 土石壩可能發生循環孔壓增加及強度改變，這與混凝土線彈性振子是不同機制。有效應力下降需以相同應力路徑和時間的資料計算，孔壓比接近某值也不能單獨宣告整座壩已液化；殘餘強度、震後排水與永久變形仍需專門材料和穩定分析。~Embankments can develop cyclic pore pressure and altered strength, mechanisms distinct from a linear concrete oscillator. Effective-stress reduction needs matching stress paths and times. A pore-pressure ratio alone cannot declare the entire dam liquefied; residual strength, post-earthquake drainage and permanent deformation still require appropriate material testing and stability analysis rather than transfer of concrete-dam assumptions. || 假設初有效垂直應力100kPa、總應力固定而超額孔壓增60kPa，ru=0.60，剩餘有效應力40kPa；非液化整體判定。~Assume initial effective vertical stress100kPa and excess pore-pressure rise60kPa at fixed total stress. ru=0.60 and remaining effective stress40kPa, not a global liquefaction verdict. || 將孔壓與總應力歷時同步，核對初始有效應力和超額孔壓的基準。比較不同土層的循環試驗與震後強度，記錄局部高孔壓位置和排水路徑，避免把單點比值推廣到所有壩體材料。~Synchronize pore-pressure and total-stress histories, checking initial effective stress and the excess-pressure reference. Compare layer-specific cyclic tests and post-shaking strength, mapping local high pressures and drainage routes without extending one point ratio to every material in the dam. || 把總孔壓誤當超額孔壓會高估累積，忽略總應力變動則可能誤判有效應力。局部弱層即使不控制平均值，也可能形成永久變形路徑，不能只看整壩平均反應。~Using total pressure instead of excess pressure overstates accumulation, while omitted total-stress variation misstates effective stress. A local weak layer can govern permanent deformation despite a modest average ratio across the wider dam body. || 土石壩的孔壓變化可直接用混凝土線彈性振子的阻尼比完全代表。~Embankment pore-pressure change is fully represented by the damping ratio of a linear concrete oscillator.
''')
META['b256']=dict(sources=['dam-dynamics','embankment-seismic','hoover-history','sisk-history'],vendorSources=['dam-dynamics','embankment-seismic'],related=['b255','b257'],summary=pair('本課把混凝土水壩的線性模態示意與土石壩孔壓機制分開，從質量、剛度、阻尼及地震輸入逐步走向水庫互制、接縫與數值收斂。十個單元均有原創計算與明確邊界，要求學徒追蹤同時刻、同座標和相同物理定義，不以單一週期或峰值吻合宣告整壩耐震合格。','The course separates linear concrete-dam modal illustrations from embankment pore-pressure mechanisms. It moves through mass, stiffness, damping and forcing to reservoir interaction, joints and numerical convergence. Ten original calculations require consistent time, coordinates and physical definitions; matching one period or peak never establishes complete seismic adequacy.'),history=pair('水壩耐震方法隨結構型式及材料機制而分化，不能以一套線性振子概括所有壩。胡佛壩官方歷史記錄一九三五年主壩混凝土澆置完成，西斯克壩則在一九六三至一九六七年建成分區土石結構，兩者在此只作材料與幾何比較。工兵團二〇〇三年手冊整理混凝土水工結構線彈性歷時分析，墾務局二〇一五年土石壩耐震章節另處理相關土壤行為。課程以可追溯出版紀錄說明方法範圍，不宣稱原創質量、剛度或孔壓值曾在這些工程量得，也不把古老工程完成年份視為現行耐震驗證。','Seismic methods differ with structural form and material mechanism; one linear oscillator cannot describe every dam. Hoover’s official history records completion of main-dam concrete in1935, while Sisk was built as a zoned embankment during1963–1967. They are used only for material and geometry comparison. The2003 USACE manual addresses linear-elastic time histories for concrete hydraulic structures, while Reclamation’s2015 embankment chapter addresses relevant soil behavior. Publication history defines scope, without presenting synthetic masses, stiffnesses or pore pressures as measurements at these landmarks or treating historical completion as current seismic verification.'),example=pair('原創敏感度：選定模態質量50000000kg與線性剛度2000000000N/m，週期T=2π√(m/k)=0.9935s。只把剛度增加10%至2200000000N/m、質量不變，週期變成0.9472s，約減少4.65%，不是減少10%。這項計算僅隔離剛度影響，沒有證明實際壩體可用補強達到此值；基礎、水庫、接縫與阻尼也可能同時改變。學徒需先寫出廣義座標和校準方法，再比較週期、模態形狀與應力位置是否一起合理。即使週期縮短，地震需求可能因輸入譜形改變而升高或降低，不能直接推論風險同步下降。','Original sensitivity: selected modal mass50000000kg and stiffness2000000000N/m give T=2π√(m/k)=0.9935s. Increase only stiffness by10% to2200000000N/m at unchanged mass; period becomes0.9472s, about4.65% shorter rather than10%. This isolates stiffness and does not establish that a real retrofit can achieve the assumed change. Foundation, reservoir, joints and damping may also vary. Define the generalized coordinate and calibration evidence before comparing period, mode shape and stress location together. Even a shorter period can increase or decrease seismic demand depending on the forcing spectrum; it cannot directly establish a corresponding reduction in risk.'),timeline=[('1935','胡佛主壩混凝土澆置完成，提供混凝土壩背景~Hoover main-dam concrete placement completes, providing concrete-dam context'),('2003','工兵團發布混凝土水工結構歷時分析手冊~USACE publishes time-history guidance for concrete hydraulic structures'),('2015','墾務局發布土石壩耐震分析章節~Reclamation publishes its embankment-dam seismic analysis chapter')],codes=['混凝土水工結構歷時分析EM1110-2-6051，二〇〇三年~Concrete Hydraulic Structure Time-History Analysis EM1110-2-6051,2003','土石壩設計標準第十三章耐震分析，二〇一五年~Embankment Dam Design Standards Chapter13 Seismic Analysis,2015'],landmarks=['胡佛壩：混凝土型式比較~Hoover Dam: concrete structural-type comparison','西斯克壩：土石材料比較~B.F. Sisk Dam: embankment-material comparison'],place=dict(name='胡佛壩公共結構背景區~Hoover Dam public structural context',country='美國~United States',lat=36.016,lng=-114.738,query='Hoover Dam Nevada Arizona'))
source('hydraulic-lab','水工實驗室技術手冊','Hydraulic Laboratory Techniques','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/mands/mands-abstracts/manabs2020.html','官方摘要確認一九八〇年手冊，涵蓋相似律、模型設計施工、設備與現地研究；算例不冒稱原文規定尺度。','Official abstract confirms the1980 manual covering similitude, model design/construction, instruments and field studies; selected scales are original assumptions.','Official indexed turn214search15 and turn218search3; date refers to publication.')
source('froude-manual','流量量測手冊佛祿數章節','Water Measurement Manual: Froude Number and Critical Flow','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/mands/wmm/chap02_12.html','官方章節說明自由水面模型佛祿數相等的概念；不代表黏滯、表面張力和氣泡效應也相等。','Official chapter explains equal Froude numbers in free-surface models; this does not also match viscosity, surface tension or air effects.','Official indexed turn214search18 confirms Froude-model context.')
source('lab-projects','水工模型研究官方目錄','Hydraulics Laboratory report catalogue','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/hydraulics_lab/reportsdb/action_list_all.cfm','官方目錄列二〇一五年克利埃勒姆魚道研究及二〇一八年福爾松附加溢洪道閘門模型；本課為方法比較。','Official catalogue lists2015 Cle Elum fish-passage studies and2018 Folsom auxiliary-spillway gate modeling; lessons compare methods rather than site results.','Official indexed turn218search8: HL-2015-02/03 and HL-2018-06 titles and dates.')
source('deltares-model','伊默伊登分層流縮尺研究','Selective Withdrawal at IJmuiden physical and numerical modeling','Deltares','https://publicwiki.deltares.nl/spaces/FRESHSALT/pages/250708679/Selective%2BWithdrawal%2Bat%2BIJmuiden','研究機構說明一比四十物理模型與三維數值比較，特別包含分層流及量測；不能將驗證限縮成外形相似。','Researcher describes1:40 physical and three-dimensional numerical comparisons with stratification and measurements; validation extends beyond geometric resemblance.','Direct research-page text turn200search3, published wiki March6,2023; cited research2021.')
compact('b257','用相似律與量測證據分辨水工縮尺模型可代表哪些現象~Use similitude and measurement evidence to define what hydraulic scale models represent',r'''
幾何比例與控制長度~Geometry ratio and reference length || 縮尺試驗先決定要研究的水理現象，再選控制長度及完整幾何範圍，不能只把外觀縮小就認為等價。非扭曲模型各方向採同一比例，局部粗糙、縫隙與邊界若無法製作應記錄；改用垂直水平不同比例時，速度與輸砂關係必須重新推導。~A model starts with the physical question, reference length and geometric domain rather than visual miniaturization. An undistorted model uses one ratio in all directions, documenting roughness, gaps or boundaries that cannot be reproduced. Different vertical and horizontal scales require rederived velocity and sediment relationships, so they cannot be introduced quietly while retaining undistorted-model formulas. || 假設原型與模型長度比λL=40，原型水深8m及長80m，模型分別0.20m與2m；所有方向採同一比例。~Assume prototype-to-model length ratio40. Prototype depth8m and length80m become0.20m and2m, with the same ratio in every direction. || 把原型及模型坐標、邊界和粗糙尺寸列成對照表，實測關鍵斷面而非只看製圖尺寸。確認是否有扭曲尺度，將無法按比例製作的縫隙獨立標出，說明可能影響哪一項觀察量。~Tabulate prototype and model coordinates, boundaries and roughness, measuring critical sections rather than relying only on drawings. Identify any distorted scale and separately mark gaps that cannot be reproduced, explaining which observed quantities their mismatch could influence. || 微小閘縫若在模型被封死會改變漏流，轉角磨圓則可能改變分離。外觀相似但垂直尺度偷偷不同時，原本的相似律不再適用，結果仍可能看起來很合理。~Closing a tiny modeled gate gap changes leakage, while rounded corners alter separation. A visually similar model with an undisclosed vertical-scale change violates the original similarity assumptions even when its output appears plausible. || 只要模型外觀像原型就可以忽略局部縫隙與尺度方向差異。~Visual similarity alone permits ignoring gaps and differences between horizontal and vertical scales.
重力流速度比例~Velocity scaling for gravity flow || 自由水面重力主導時以佛祿數相等建立速度比例，必須確認原型與模型使用相同重力場。此時速度不是隨長度線性縮小，且黏滯或表面張力主導的小尺度區仍可能失真；同一速度比例也不能無條件套到加壓水錘或可壓縮氣流。~For gravity-dominated free surfaces, equal Froude numbers determine velocity scaling under equal gravity. Velocity does not shrink linearly with length, and small viscous or capillary regions may remain distorted. The same relation cannot automatically describe pressurized water hammer or compressible air, whose controlling physics and required similarity parameters differ from the chosen free-surface experiment. || 假設λL=40且佛祿相似，原型速度8m/s，模型Vm=8/√40=1.2649m/s；不保證雷諾相似。~Assume length ratio40 and Froude similarity. Prototype velocity8m/s gives Vm=8/√40=1.2649m/s, without guaranteeing Reynolds similarity. || 分別用原型與模型水深計算佛祿數，查核速度量測位置是否對應。再估黏滯與表面張力影響範圍，區分局部薄水層和主要流區，不以整體相似掩蓋小尺度區域的失真。~Compute Froude numbers independently using corresponding depths and velocity locations. Estimate where viscosity and surface tension matter, separating thin local layers from the main flow rather than hiding small-scale distortion behind a matching global similarity parameter. || 將速度也縮小四十倍會使流態和波速錯位，僅調整入流直到外觀看似相同也可能改變水深。局部黏性控制區即使佛祿數正確，壓力和渦流仍未必可直接放大。~Reducing velocity fortyfold misrepresents flow regime and wave propagation, while adjusting inflow merely to match appearance may change depth. Locally viscous regions can still have unrepresentative pressures and vortices despite equal Froude numbers. || 佛祿相似要求速度與模型長度使用完全相同的縮小倍數。~Froude similarity requires velocity to use exactly the same reduction factor as length.
總流量縮尺次方~Total-discharge scale exponent || 總流量是斷面面積乘速度，非扭曲重力模型的面積按長度平方、速度按平方根縮放，因此總流量有不同次方。單位寬度流量另有分母，兩者不能混用；量測管路與模型入口也需一致，旁通或溢流未記錄會破壞整體收支。~Total discharge combines cross-sectional area with velocity. An undistorted gravity model scales area with length squared and velocity with its square root, producing a distinct exponent. Unit-width discharge has a different denominator and cannot use the same rule. Measurement piping, bypasses and overflow must also match the model boundary to preserve the water balance. || 假設λL=40、原型總Q=1000m³/s，模型Qm=Qp/λL^(5/2)=0.09882m³/s；不是單位寬度流量比例。~Assume length ratio40 and prototype total discharge1000m³/s. Model Qm=Qp/λL^(5/2)=0.09882m³/s, distinct from unit-width discharge scaling. || 從面積與速度比例逐步推導流量次方，確認資料標示總流量或每米寬度。以獨立容積時間法查核流量計，記錄旁通與回流，並將校正範圍對照實際模型所需的小流量。~Derive the exponent from area and velocity and label total versus per-width discharge. Check the flow meter independently by volume and time, recording bypass and recirculation and comparing its calibration range with the small discharge actually required by the model. || 把每米流量的次方用在總流量會差一個長度比例，低流量儀器超出校正範圍又會加深誤差。水面看似接近時，仍可能因錯誤流量造成錯誤能量與消能判讀。~Using the unit-width exponent for total discharge introduces an entire length-scale error, compounded if the meter operates outside calibration. Similar-looking water levels can still conceal incorrect energy and dissipation because the delivered discharge is wrong. || 總流量與每米寬度流量在縮尺模型都使用同一比例次方。~Total discharge and discharge per unit width use the same scaling exponent.
時間縮尺與記錄~Time scaling and recording || 重力模型的時間比例由長度除速度得到，原型漫長變化會在模型較短時間內發生。儀器取樣率、閥門運動與入流變化需同步配合，不能只縮放最後結果而保留原型的操作時間；資料對齊也應記錄起始事件，避免把時間偏移誤認為物理遲滯。~Gravity-model time follows length divided by velocity, compressing long prototype changes into shorter experiments. Sampling, actuator movement and inflow variation must be synchronized accordingly, rather than scaling outputs while retaining prototype operating duration. Records also require a defined start event so clock offsets are not mistaken for physical lag in the measured hydraulic response. || 假設λL=40，原型事件120s，模型時間tm=120/√40=18.974s；只適用所選重力相似過程。~Assume length ratio40 and prototype duration120s. Model tm=120/√40=18.974s, applying only to the selected gravity-similar process. || 把入流、閥位與量測通道放在共同時間軸，明列原型與模型的換算。以可辨識水波事件校核時鐘和觸發延遲，檢查最快變化是否仍有足夠資料，不讓儀器更新頻率主導試驗結果。~Align inflow, valve position and sensor channels on a common clock and document both time scales. Check triggers against an identifiable wave event and verify resolution of the fastest changes so instrument refresh limits do not govern the apparent experimental response. || 閥門動作沒有縮時會讓模型充水過慢，取樣頻率不足又會漏掉短峰值。事後把時間軸乘比例，不能補回試驗當時沒有正確重現的邊界變化。~An unscaled actuator duration makes filling too slow, and sparse sampling misses short peaks. Multiplying the time axis afterward cannot restore boundary changes that were not correctly reproduced while the physical experiment was running. || 只要事後修改時間軸就能補救試驗時未縮尺的閥門動作。~Rescaling the recorded time axis repairs any valve motion that was not correctly scaled during the test.
壓力尺度與氣泡~Pressure scale and air effects || 相同液體密度與重力下，重力壓力尺度隨長度比例改變，但絕對氣壓不會自動跟著縮小。模型氣泡、負壓和空化可能因此偏離原型，尤其局部高速與衝擊區；靜水或重力動壓的可放大性不能被解釋成所有瞬態壓力都相似。~At matched liquid density and gravity, gravity-pressure scale follows length, but ambient absolute pressure does not automatically scale. Air bubbles, suction and cavitation can therefore differ from the prototype, especially in high-speed or impact regions. Scaling hydrostatic or gravity-dominated pressure does not establish similarity of every transient pressure mechanism within the same apparatus. || 假設λL=40、同密度重力壓力原型60kPa，模型壓力1.50kPa；此為表壓重力尺度，不代表絕對氣壓也縮四十倍。~Assume length ratio40 and matched density. Prototype gravity gauge pressure60kPa scales to1.50kPa, without scaling ambient absolute air pressure fortyfold. || 記錄壓力是表壓或絕對壓力並核對零點，區分慢變重力壓與短時衝擊。觀察氣泡和通氣路徑，將空化相關區域單獨標註，必要時以不同尺度或專門裝置檢驗未相似的機制。~Label gauge versus absolute pressure and verify zero, separating slow gravity loading from brief impact. Observe bubbles and ventilation paths, flag cavitation-sensitive regions and use alternative scales or specialized facilities where needed to examine mechanisms not represented by the chosen similitude. || 封閉空氣團的壓縮在模型可能比原型更顯著，直接放大尖峰會誤判結構荷載。把表壓負值當成低於蒸氣壓，亦會在沒有絕對壓力基準時錯判空化。~Trapped-air compression can be disproportionately important in the model, making direct scaling of peaks misleading. A negative gauge reading also cannot establish pressure below vapor pressure without the corresponding absolute-pressure reference. || 重力壓力比例正確就表示空化與封閉氣泡壓縮也完全相似。~Correct gravity-pressure scaling proves that cavitation and trapped-air compression are also fully similar.
合力尺度與量測~Force scaling and measurement || 壓力積分成合力時還要乘面積，所以同密度重力模型的力比例是長度三次方。量測裝置的剛度、頻率和支架阻流可能改變原本流場，模型力很小時摩擦和纜線也可能重要；不能僅因荷重元件讀值穩定就認為力傳遞已被完整量到。~Integrating pressure over area gives a cubic length scale for force under matched-density gravity similarity. Sensor stiffness, natural frequency and support blockage can alter the flow, and friction or cables become significant when model forces are small. Stable readings alone do not establish that the complete intended load path reaches the calibrated measuring device. || 假設λL=40、原型重力主導合力2MN，模型Fm=2000000/40³=31.25N；未處理感測器動態或氣泡衝擊。~Assume length ratio40 and prototype gravity-dominated force2MN. Model Fm=2000000/40³=31.25N, excluding sensor dynamics and air-impact scaling. || 以已知方向和位置的砝碼校核整套力傳遞路徑，記錄支架自振頻率及零漂。比較壓力積分與總力感測器結果，檢查水流是否繞過或推到未量測的支架，不只校正單顆感測元件。~Calibrate the full load path using known weights and positions, recording support frequency and zero drift. Compare integrated pressure with measured resultant and check whether water loads bypass the sensor or act on unmeasured supports rather than calibrating only the isolated transducer. || 支架摩擦可能承擔部分荷重，使感測器低估；共振則可能放大短峰值。兩種偏差都能在靜態校正看似良好時出現，必須查核水中實際動態條件。~Support friction can carry load away from the sensor, while resonance amplifies short peaks. Both errors can occur despite satisfactory static calibration and require examination under the actual submerged dynamic conditions of the experiment. || 縮尺合力只需要跟長度成正比而不必考慮受壓面積。~Model force scales only linearly with length and does not depend on loaded area.
雷諾數與黏滯失真~Reynolds number and viscous distortion || 使用同一水體且採佛祿相似時，模型速度和長度都變小，雷諾數不能同時保持。主要流區可能仍是紊流，但薄水層、近壁與小縫可能受黏滯控制；不能用一個全域雷諾數宣稱所有局部現象相似，應檢查尺寸改變後結果是否穩定。~With the same fluid under Froude similarity, both velocity and length decrease, so Reynolds number is not preserved. Main flow may remain turbulent while thin layers, walls and gaps become viscosity-sensitive. One global Reynolds number cannot qualify every local phenomenon; comparing more than one scale helps determine whether the measured result depends on the altered viscous regime. || 假設ν=10⁻⁶m²/s，以水深為控制長度，模型V=8/√40m/s、h=0.20m，Re≈252982；原型V=8m/s、h=8m，Re=64000000。~Assumeν=10⁻⁶m²/s, using depth as the reference length. Model V=8/√40m/s,h=0.20m gives Re≈252982; prototype V=8m/s,h=8m gives Re=64000000. || 用真正控制局部現象的長度估雷諾數，記錄水溫對黏度的影響，不能只選最大池寬。比較至少兩尺度的壓損、分離或薄層行為，保留不能可靠外推的區域與觀察量。~Estimate Reynolds number using lengths controlling the local mechanism and record temperature-dependent viscosity rather than automatically choosing maximum basin width. Compare losses, separation or thin layers at multiple scales and retain explicit limits for quantities that cannot be reliably extrapolated. || 大水槽的全域雷諾數很高仍可能有層流閘縫，若把局部漏流按紊流比例放大，會算錯。溫度變化又可能在同一模型內改變黏度，使重複試驗不完全可比。~A high basin-scale Reynolds number can coexist with a laminar gate gap, invalidating turbulent leakage scaling. Water-temperature changes also alter viscosity between repeated tests, so nominally identical geometry and discharge need not give directly comparable local behavior. || 模型主流雷諾數高就可以證明每個細縫和近壁區都與原型相似。~A high main-flow Reynolds number proves similarity in every small gap and near-wall region.
韋伯數與表面張力~Weber number and surface tension || 表面張力對小尺度水舌、液滴與薄膜相對重要，重力縮尺通常不會保留慣性與表面張力之比。模型看見的破碎、噴濺或氣泡大小可能因此失真，不能以外觀照片當定量證據；若研究問題正是這些現象，需要另選尺度或承認觀察僅能定性。~Surface tension matters disproportionately for small jets, drops and films, and gravity scaling generally does not preserve its ratio to inertia. Breakup, spray and bubble size can therefore be distorted, making photographs insufficient quantitative evidence. If these phenomena are the study objective, a different scale or explicit qualitative limitation is needed rather than assuming visual similarity guarantees the physics. || 假設ρ=1000kg/m³、σ=0.072N/m、模型V²=1.6m²/s²、L=0.20m，We=ρV²L/σ=4444.4；原型值是其1600倍。~Assumeρ=1000kg/m³,σ=0.072N/m,model V²=1.6m²/s² and L=0.20m. We=4444.4; the corresponding prototype value is1600times larger. || 先指定表面張力影響的局部長度，記錄水質、溫度及表面污染，查核材料是否改變潤濕。比較不同尺度水舌破裂和噴濺，將可量化水位與只宜定性解讀的液滴外觀分開。~Define the local length relevant to surface tension and record temperature, water condition and contamination, checking altered wetting on model materials. Compare jet breakup and spray across scales, separating quantitatively useful levels from droplet appearances that support only qualitative interpretation. || 模型小液滴可能被表面張力束縛，原型卻更易破碎，直接按照片估曝氣會偏差。加入界面活性物質改變張力時，也可能連帶改變氣泡與量測條件，不能當簡單修補。~Small model droplets can remain surface-tension-bound where prototype flow breaks up, biasing air-entrainment estimates from imagery. Surfactant adjustments also change bubbles and measurement conditions and cannot be treated as an uncomplicated correction to all scale effects. || 重力相似已經自動保證液滴尺寸與曝氣程度都能直接放大。~Gravity similarity automatically makes droplet size and air entrainment directly scalable.
讀值誤差的放大~Scaling measurement uncertainty || 模型的微小讀值誤差放回原型後也按相應比例放大，不能以數字小就忽略。讀值重複性、共同零點及尺度製造誤差屬不同分量，必須說明相關性後再合成；原型結果的小數位應反映證據，而不是把模型儀器的每一位都乘出來展示。~Small model reading errors grow under prototype scaling and cannot be dismissed by their absolute size. Repeatability, coherent zero offset and fabrication-scale error are distinct components requiring stated correlations before combination. Reported prototype precision should follow the evidence, not every digit produced by multiplying an instrument display by the geometric ratio in a spreadsheet. || 假設模型水位標準不確定度0.0005m、λL=40且比例視為精確，原型相應標準不確定度0.020m；未含尺度本身誤差。~Assume model level standard uncertainty0.0005m and exact length ratio40. Prototype-equivalent uncertainty is0.020m, excluding uncertainty in the scale itself. || 分開估水位零偏、讀值散布及模型尺寸誤差，說明哪些為共同分量。以獨立控制點檢核高程，將量測及尺度不確定度傳播到原型結果，按有效精度四捨五入，不使用無依據的小數位。~Estimate level bias, reading scatter and fabrication error separately, identifying shared components. Check elevations against independent control, propagate measurement and scale uncertainty to prototype results and round to defensible precision rather than retaining unsupported decimal places. || 水位零偏在所有測點共同存在時不會靠平均消失，尺度錯誤還可能同時影響水深和流量。只放大平均讀值而不放大誤差，會讓原型推估看起來過度精確。~A shared level offset survives averaging, and incorrect scale can affect both depth and discharge. Scaling the mean reading without its uncertainty makes the inferred prototype result appear more precise than the experiment actually supports. || 模型讀值誤差很小所以換算回原型後可以完全忽略不計。~A small model reading error can be ignored completely after conversion to prototype scale.
重複試驗與代表性~Replicates and representativeness || 重複試驗能估計同條件下的散布，但三次重複不能涵蓋未測水位、流量或邊界狀態。平均值標準誤與單次觀測標準差用途不同，獨立性也需要重新建立初始條件；若同一零點偏差持續存在，增加次數只會讓錯誤平均顯得更穩定。~Replicates estimate scatter under one condition but do not cover untested levels, discharges or boundaries. Standard error of a mean differs from the deviation of individual observations, and independence requires reestablishing initial conditions. A persistent zero bias is not reduced by replication; more runs can merely make the wrong mean appear increasingly stable and convincing. || 假設獨立流量結果0.098、0.100、0.102m³/s，平均0.100、樣本標準差0.002m³/s，變異係數2%；非全部工況不確定度。~Assume independent discharges0.098,0.100,0.102m³/s. Mean0.100 and sample deviation0.002m³/s give2% coefficient of variation, not uncertainty for all operating conditions. || 事先定義重複方式和回復初始水位程序，保留每次原始紀錄與共同校正資料。用樣本而非母體分母計標準差，另列未試工況矩陣，避免以少量重複的低散布宣稱整個模型已驗證。~Define repetition and initial-level restoration beforehand, retaining raw runs and shared calibration records. Use the sample-deviation denominator and list the untested condition matrix separately, without interpreting low scatter from a few replicates as complete validation of the model domain. || 三次都受同一流量計偏差時仍可非常一致，卻系統性偏離真值。挑掉不喜歡的試驗又會縮小散布，若沒有預定排除規則，所謂重複性可能只反映選擇性報告。~Three runs sharing one meter bias can agree closely while all miss the true value. Selective deletion shrinks scatter further, and without predefined exclusion criteria apparent repeatability may reflect reporting choices rather than reliable experimental behavior. || 重複三次結果很接近就代表所有未測工況與系統偏差都已驗證。~Three closely agreeing repeats validate every untested condition and eliminate systematic bias.
''')
META['b257']=dict(sources=['hydraulic-lab','froude-manual','lab-projects','deltares-model'],vendorSources=['hydraulic-lab','deltares-model'],related=['b256','b281'],summary=pair('本課以非扭曲自由水面重力模型為主軸，逐步推導幾何、速度、流量、時間、壓力與合力比例，再檢查雷諾數、韋伯數及量測誤差無法自動相似的部分。十個單元要求先說明研究目的與控制尺度，再判斷哪些結果可量化放大，哪些只能定性比較，避免以模型照片漂亮取代實驗驗證。','An undistorted gravity-driven free-surface model provides the main thread. Units derive geometry, velocity, discharge, time, pressure and force scales, then examine Reynolds and Weber mismatches and measurement uncertainty. Apprentices define the question and controlling length before deciding which results support quantitative extrapolation and which allow only qualitative comparison.'),history=pair('水工模型的價值來自可控制邊界並檢查機制，而不是宣稱微縮模型包含全部原型物理。墾務局一九八〇年水工實驗室技術手冊整理相似律、製作與量測方法，後續量水手冊解釋佛祿數在自由水面模型的角色。官方研究目錄列二〇一五年克利埃勒姆魚道模型及二〇一八年福爾松附加溢洪道閘門研究，顯示不同問題需要不同觀察量。Deltares另以伊默伊登分層流模型比較物理與數值結果。本課所有尺寸與流量獨立假設，不將案例曾用模型解釋成任意縮尺都可信。','Physical models offer controlled boundaries and mechanism checks rather than containing every prototype process in miniature. Reclamation’s1980 laboratory manual organizes similitude, fabrication and measurement, and its water-measurement guidance explains Froude similarity for free surfaces. The official catalogue lists2015 Cle Elum fish-passage studies and2018 Folsom auxiliary-spillway gate work, illustrating different questions and observations. Deltares separately compares physical and numerical stratified-flow models at IJmuiden. All dimensions and flows here are independently assumed; the existence of a landmark model study does not imply that any chosen reduction scale is reliable.'),example=pair('原創縮尺敏感度：原型總流量1000m³/s，長度比例40，依佛祿相似Qm=1000/40^(5/2)=0.09882m³/s。若為節省實驗空間把比例增加10%至44，原型保持不變，所需模型流量降為1000/44^(5/2)=0.07787m³/s，約減少21.20%，並不是只減少10%。此時模型尺度更小，黏滯和表面張力相對影響反而更值得查核。學徒應重算速度、時間、感測器量程與誤差放大，確認試驗台是否能穩定提供較小流量。不能只因用水減少就認為改尺度必然改善研究品質。','Original scale sensitivity: a prototype discharge of1000m³/s with length ratio40 requires Qm=1000/40^(5/2)=0.09882m³/s under Froude similarity. Increasing the ratio by10% to44 to save laboratory space while retaining the same prototype reduces flow to1000/44^(5/2)=0.07787m³/s, about21.20% rather than10%. The smaller model makes relative viscous and capillary effects more important to check. Recalculate velocity, timing, sensor range and uncertainty amplification, then verify that the rig can reliably provide the lower discharge. Reduced water demand alone does not establish that the revised scale improves the quality of the experiment.'),timeline=[('1980','墾務局出版水工實驗室技術手冊~Reclamation publishes its Hydraulic Laboratory Techniques manual'),('2015','官方目錄列克利埃勒姆魚道模型研究~Official catalogue lists Cle Elum fish-passage model studies'),('2018','官方目錄列福爾松附加溢洪道閘門模型~Official catalogue lists Folsom auxiliary-spillway gate modeling')],codes=['水工實驗室技術手冊，一九八〇年~Hydraulic Laboratory Techniques manual,1980','流量量測手冊第二章佛祿數與臨界流~Water Measurement Manual Chapter2, Froude number and critical flow'],landmarks=['克利埃勒姆壩：魚道模型研究~Cle Elum Dam: fish-passage model studies','福爾松附加溢洪道：閘門模型研究~Folsom auxiliary spillway: gate model studies'],place=dict(name='福爾松公共水工研究背景區~Folsom public hydraulic-study context',country='美國~United States',lat=38.708,lng=-121.158,query='Folsom Dam California'))

source('pumped-storage','抽蓄水力發電基本原理','Pumped Storage Hydropower','US Department of Energy','https://www.energy.gov/cmei/water/pumped-storage-hydropower','官方說明上下庫儲能、抽水耗能及開放與封閉循環差異；本課不使用即時市場價格或宣稱通用排程。','Official explanation of two-reservoir storage, pumping energy and open versus closed loops; no current market prices or universal schedule are inferred.','Opened turn238view1, lines14 and25–33.')
source('psh-guide','抽蓄價值評估指南與工具','Pumped Storage Valuation Guidebook and Tool','US Department of Energy','https://www.energy.gov/cmei/water/articles/new-guidebook-and-tool-help-developers-calculate-value-potential-pumped-storage','二〇二二年官方介紹國家實驗室指南與二〇二一年工具發布，支持明確列出服務與分析邊界，不提供現場水位指令。','The2022 official article describes laboratory valuation guidance and the2021 tool release, supporting explicit service and analysis boundaries rather than field water-level instructions.','Opened turn240view1: March9,2022 article, tool released November2021, fifteen-step framework.')
source('bath-storage','巴斯郡抽蓄電站','Bath County Pumped Storage Station','Dominion Energy','https://www.dominionenergy.com/about/making-energy/hydroelectric-power-facilities/bath-county-pumped-storage-station','業主記錄上下庫及一九八五年十二月商轉；作抽蓄配置案例，所有本課流量、水頭與效率均另行假設。','Owner records two reservoirs and December1985 commercial operation; course flows, heads and efficiencies are separately assumed.','Opened turn240view0, lines265–278; no capacity or water-level limit is prescribed by this lesson.')
source('elbert-storage','埃爾伯特抽蓄電站官方資料','Mt. Elbert Pumped-Storage Powerplant data','US Bureau of Reclamation','https://www.usbr.gov/projects/pdf.php?id=46','官方電站資料確認抽蓄型式與機組，僅作另一配置比較，不由歷史發電圖推算現在調度或效率。','Official plant data confirms pumped-storage configuration and units; historical generation charts are not used to infer current dispatch or efficiency.','Opened eight-page official PDF turn238view3, title and unit table.')
source('hydro-structures','水力電廠結構規劃與設計','EM1110-2-3001 Planning and Design of Hydroelectric Power Plant Structures','US Army Corps of Engineers','https://www.publications.usace.army.mil/Portals/76/Publications/EngineerManuals/EM_1110-2-3001.pdf','官方目錄列二〇〇八年十月更新的水力電廠結構手冊，涵蓋壓力管與調壓設施；不是每座場址的操作規程。','Official catalogue lists the October2008 update of hydroelectric structural guidance, including penstocks and surge facilities; it is not a site operating procedure.','Official indexed turn237search9 and turn237search40;2008 update of1995 manual, not a project opening date.')
compact('b258','以雙庫水量與能量守恆建立可追溯的抽蓄水位排程~Build traceable pumped-storage schedules using paired-reservoir water and energy balances',r'''
雙庫水量帳本~Paired reservoir water balance || 抽蓄把水在上下庫之間搬移，不會因為發電而消耗同等體積的水，但外部入流、蒸發與放流仍要分別列帳。每個時間步都應同時更新兩庫，明確約定流量正方向；只看上庫水位容易掩蓋下庫已滿或總水量不守恆的排程錯誤。~Pumped storage transfers water between reservoirs without consuming the transferred volume through generation, although external inflow, evaporation and release remain separate terms. Update both reservoirs at every interval with explicit flow signs. Tracking only the upper level can hide a full lower reservoir or a schedule that violates total water conservation. || 假設無外部交換，發電流量100m³/s持續1800s，上庫減少180000m³、下庫增加同量，兩庫合計不變。~Assume no external exchange and generation flow100m³/s for1800s. Upper storage falls180000m³ while lower storage rises equally, preserving their combined volume. || 建立上庫與下庫兩欄逐時帳本，逐一核對抽水及發電符號並把外部交換獨立列出。以兩庫總量閉合差找單位或漏項錯誤，再確認每步結果沒有超過個別可用容積邊界。~Build separate time-step ledgers, checking pumping and generating signs and listing external exchanges explicitly. Use total-volume closure to locate unit errors or omissions, then confirm each step remains inside both reservoirs’ individual usable-storage bounds. || 將同一流量在兩庫都列成流出會製造虛假耗水，反過來都列入流又會創造水量。日終總量碰巧正確也不能證明中途下庫未經溢流或超界。~Entering a transfer as outflow from both reservoirs invents losses, while dual inflow creates water. A correct daily total does not prove that intermediate lower-reservoir storage avoided overflow or other boundary violations. || 只要日終上庫水位正確就不需要檢查下庫逐時水量。~A correct final upper-reservoir level removes any need to check lower-reservoir storage through time.
水位庫容換算~Level and storage conversion || 水位不是可直接加減的能量刻度，必須透過測得的庫容曲線換成水量。局部面積不變只適合小範圍近似，廣大的淺灘或陡岸會改變同一水量對應的水位變化；上下庫曲線也不能混用，即使它們具有相近的最大面積。~Water level is not an additive energy scale; surveyed storage curves connect level to volume. A constant surface area is a local approximation, and broad shelves or steep banks change the level response to equal transfers. Upper and lower curves are not interchangeable merely because their maximum surface areas appear similar. || 假設局部上庫面積600000m²恆定，抽入180000m³，Δz=ΔV/A=0.300m；大範圍水位需積分實際庫容曲線。~Assume locally constant upper area600000m² and inflow180000m³. Δz=ΔV/A=0.300m; broader changes require the actual integrated storage curve. || 將水位、庫容及面積資料用共同高程基準整理，檢查曲線斜率是否等於水面面積。以已知移水量回算兩庫水位並比較實測殘差，遇到灘地轉折時縮短時間步或直接用曲線求解。~Put level, storage and area on a common datum and check that storage-curve slope equals surface area. Back-calculate levels from known transfers, inspect measured residuals and resolve shoreline breaks with smaller steps or direct curve inversion. || 將平方公里當成平方米會使水位變化嚴重失真，沿用過期地形也會錯估可用容積。感測器高程基準偏移時，曲線再精細也不能修復錯誤輸入。~Confusing square kilometers with square meters grossly distorts level change, and outdated bathymetry misstates usable storage. A detailed curve cannot correct a sensor referenced to the wrong elevation datum. || 同樣的移水量在上下庫必定造成完全相同的水位變化。~The same transferred volume must produce identical level changes in both reservoirs.
毛水頭與淨水頭~Gross and net head || 上下游水面高差是毛水頭，機組可利用的淨水頭還受沿程與局部損失影響，且損失隨流量及模式改變。把泵送和發電套同一個帶符號的效率可能混淆能量方向；先畫能量線，才能知道損失在哪一側增加需求或減少輸出。~The reservoir-level difference is gross head, while usable turbine head also depends on distributed and local losses that vary with flow and mode. Applying one signed efficiency to both pumping and generation obscures energy direction. An energy-grade sketch identifies where losses increase pumping demand or reduce generating output for the chosen operating point. || 假設上庫600m、下庫200m、發電水頭損失15m，淨水頭H=600−200−15=385m；未代表其他流量的損失。~Assume upper elevation600m, lower200m and generation loss15m. Net headH=600−200−15=385m, without prescribing losses at other discharges. || 用同時刻的上下庫水位建立毛水頭，逐項標註流道損失與量測位置。核對泵送時損失應加到所需揚程，發電時則扣除，並以不同流量資料檢查固定損失假設的適用範圍。~Calculate gross head from simultaneous levels and label each loss and measurement location. Verify that pumping adds losses to required lift while generation subtracts them, then use different flow observations to test the limited range of a constant-loss approximation. || 水位資料時間不一致會創造不存在的水頭，將損失重複扣除會低估輸出。忽略低水位進水條件與空化限制，也可能讓數學上可行的排程超出機組適用範圍。~Unsynchronized levels create a fictitious head, and double-counted losses understate output. Neglecting low-level intake and cavitation constraints can also place an arithmetically feasible schedule outside the machine’s permitted operating envelope. || 毛水頭與機組淨水頭在所有流量下都完全相等。~Gross reservoir head and machine net head are equal at every discharge.
發電功率與輸出~Generating power and output || 水力功率由流量與淨水頭共同決定，電輸出還要乘適用工況的總效率。額定容量只是設備界限而不是每一時刻都能供應的功率；水位下降、效率曲線或流道限制會改變結果，排程應保存每步輸入而非只指定固定兆瓦數。~Hydraulic power depends jointly on discharge and net head, with electrical output reduced by the efficiency appropriate to that condition. Nameplate capacity is an equipment bound rather than power available at every instant. Changing level, efficiency curves and waterway limits require stored stepwise inputs instead of simply assigning a constant megawatt output. || 假設單一工況ρ=1000kg/m³、Q=100m³/s、淨水頭385m、總效率0.90，P=ρgQHη=339.9165MW。~Assume density1000kg/m³, discharge100m³/s, net head385m and overall generating efficiency0.90. P=ρgQHη=339.9165MW at this stated operating point. || 分清機械、發電機與總效率的定義，避免把同一損失計算兩遍。以每步流量和淨水頭算功率，積分成電能後對照電表，同時保留啟停、輔機與不可運轉區域的獨立紀錄。~Distinguish mechanical, generator and overall efficiency to avoid duplicated losses. Compute each step’s power from discharge and net head, integrate to energy and compare with meters while separately retaining starts, auxiliary loads and prohibited operating regions. || 將百分之九十直接代成九十會放大百倍，忽略功率與電能的時間轉換則使排程帳本失衡。用額定效率覆蓋全部負載，也可能系統性高估低負載輸出。~Entering ninety instead of0.90 inflates output a hundredfold, while omitting the time conversion confuses power and energy. Extending rated efficiency to every load can systematically overstate output away from the reference condition. || 額定發電容量足夠就保證任意水位都能連續輸出相同功率。~Adequate nameplate capacity guarantees identical continuous output at any reservoir level.
抽水輸入與損失~Pumping input and losses || 抽水必須提供提升水體與克服損失所需的能量，因此電輸入除以效率而不是乘以效率。泵的穩定運轉範圍、可變速能力及轉換時間會影響流量是否可調；能源帳本可比較方案，但不能把連續公式直接當成每座固定轉速機組的控制命令。~Pumping input must cover both elevation gain and hydraulic losses, so electrical demand divides by efficiency rather than multiplying it. Stable pump range, speed flexibility and mode-transition time determine whether discharge can actually be varied. An energy ledger can compare options without turning a continuous formula into an operating command for every fixed-speed unit. || 假設抽水流量100m³/s、總揚程415m、電至水效率0.88，Pin=1000×9.81×100×415/0.88=462.631MW。~Assume pumping discharge100m³/s, total lift415m and electricity-to-water efficiency0.88. Pin=1000×9.81×100×415/0.88=462.631MW, excluding any separately modeled auxiliaries. || 在同一能量邊界記錄泵輸入與水體得到的能量，標註效率是否已含馬達及變頻設備。檢查機組曲線與模式切換時段，將不可行的中間流量排除，再用電表積分核對假設效率。~Record pump input and water-energy gain across the same boundary, noting whether motor and converter losses are included. Check machine curves and mode transitions, exclude infeasible intermediate flows and compare metered energy with the assumed aggregate efficiency. || 將效率相乘會得到比水力需求還小的電輸入，違反能量守恆。若輔機已含在總效率又再扣一次，亦會錯估整個循環的損失與可回收電量。~Multiplying by efficiency produces electrical input below the water-energy requirement and violates conservation. Counting auxiliaries both within aggregate efficiency and separately also misstates cycle loss and recoverable electrical output. || 抽水效率越低時用電需求反而應該越小。~Lower pumping efficiency should reduce the electrical input required for the same lift and flow.
往返效率的邊界~Round-trip efficiency boundaries || 往返效率應以完整且一致的週期比較輸入與輸出，起終庫存不同時不能把借用的水能誤當效率提升。定水頭理想化下兩個方向效率相乘很方便，但水頭損失和輔機仍要說明；不同計量邊界的結果不可直接排名優劣。~Round-trip efficiency compares input and output over a complete cycle with consistent boundaries. Different terminal storage can make borrowed water energy look like improved efficiency. Multiplying directional efficiencies is convenient under equal constant head, but hydraulic loss and auxiliaries must be stated, and values measured across different boundaries should not be ranked as equivalent. || 假設相同定水頭且起終庫存相同，抽水效率0.88、發電效率0.90，往返ηrt=0.88×0.90=0.792即79.2%。~Assume equal constant head and identical initial and final storage. Pumping efficiency0.88 and generating efficiency0.90 give round-tripηrt=0.792, or79.2%. || 列出週期起終兩庫水位、輸入電能與輸出電能，校正外來水量造成的能量改變。註明是否計入待機及變壓器損失，只有邊界相同時才比較往返效率，並保留原始電表時間區間。~List initial and final levels in both reservoirs and metered input and output, correcting for energy introduced by external water. State treatment of standby and transformer losses and compare round-trip figures only across matching boundaries and time intervals. || 若日終上庫比起初低，額外發電可能只是消耗庫存。把這部分輸出除以當日抽水電量會出現虛高甚至超過百分之百的結果，卻不是無損儲能。~Ending with a lower upper reservoir can add generation by consuming inventory. Dividing that output by only the day’s pumping input yields inflated or even above-unity efficiency without demonstrating lossless storage. || 只要輸出電量除以當日抽水電量超過一就證明儲能效率超過百分之百。~Output exceeding the same day’s pumping input proves a storage efficiency above one hundred percent.
可用水量與時數~Usable volume and duration || 儲能時數受可移動水量及可接受流量共同限制，不等同於水庫總容積除以任意大流量。死水位、下庫空間、最低淹沒深度和保留需求會縮小可用範圍；長時間輸出還會改變水頭，所以等流量時數只提供第一層水量檢核。~Storage duration is limited by transferable water and feasible discharge, not total reservoir volume divided by any desired flow. Dead storage, lower-reservoir room, intake submergence and reserved water reduce the usable range. Head changes during a long release, so constant-discharge duration provides only the first water-balance check rather than constant-power endurance. || 假設已扣保留量的可移水量720000m³、定流量100m³/s，t=720000/100=7200s即2h；不保證定功率兩小時。~Assume transferable volume720000m³ after reservations and constant discharge100m³/s. Duration7200s equals2h, without guaranteeing constant electrical power throughout. || 從上下庫限制交集求可移水量，逐項列出死庫容與保留用途，避免直接用最大庫容。沿兩小時路徑更新水頭和效率，檢查下庫、進水淹沒及機組界限，最後才給出可交付電能。~Derive transferable volume from the intersection of both reservoirs’ constraints, explicitly subtracting dead storage and reservations. Update head and efficiency along the two-hour path, checking lower storage, intake submergence and machine limits before reporting deliverable energy. || 上庫仍有水不代表下庫還有接收空間，最低進水淹沒也可能先被觸及。將定流量的時數宣稱為額定功率時數，會忽略逐步減少的水頭及效率變動。~Water remaining upstream does not imply space downstream, and minimum intake submergence may bind first. Reporting constant-flow duration as rated-power endurance ignores falling head and changing efficiency during release. || 只要上庫尚未排空就可以維持額定功率直到最後一滴水。~Rated power can be maintained until the upper reservoir is completely empty.
爬坡流量積分~Integrating flow ramps || 排程時間步內的流量若持續變化，採末端值代表整段會錯估移水量。線性爬坡可用梯形積分，但真實閥門和機組反應未必線性；較慢的水量排程也不能取代水錘檢查，因為相同總移水量可能對應完全不同的瞬態壓力。~A changing discharge should not be represented by its final value over the whole interval. A linear ramp permits trapezoidal integration, although real actuators and machines may respond nonlinearly. Slow scheduling calculations do not replace water-hammer checks because equal transferred volume can arise from very different pressure-transient histories in the waterway. || 假設流量在300s內由0線性升至100m³/s，V=(0+100)×300/2=15000m³；此為水量積分而非水錘驗算。~Assume discharge rises linearly from0 to100m³/s in300s. Transferred V=15000m³ by trapezoidal integration, not a water-hammer assessment. || 保留流量歷時並檢查爬坡形狀，將梯形積分與較短時間步積分比較。另把閥位、轉速及壓力歷時送到瞬態分析，清楚標註此水量帳本沒有證明閥門速度或壓力變化可被接受。~Retain the discharge history, check ramp shape and compare trapezoidal integration with smaller time steps. Examine valve, speed and pressure histories in a separate transient analysis, explicitly recording that the volume ledger does not approve actuator rates or pressure excursions. || 以末端一百立方米每秒乘全段會把移水量加倍，造成下一時段庫位預測偏移。即使水量積分正確，短暫快速動作仍可能產生排程模型看不到的壓力波。~Using the final discharge over the full interval doubles this transferred volume and biases the next storage estimate. Correct integration still cannot reveal short rapid actions that generate pressure waves outside the scheduling model. || 爬坡期間總水量正確就能證明任何閥門動作都不會產生水錘。~A correct total ramp volume proves that every associated valve movement is free of water hammer.
外部水量與封閉循環~External water and closed loops || 封閉循環表示缺乏持續天然水體連通，並不代表沒有降雨、蒸發、滲漏或補水。這些小流量累積後會改變長期可用庫存，兩庫表面積不同又會造成不對稱損失；調度帳本要分清天氣水量與機組搬移，才能找到真實偏差來源。~A closed loop lacks an ongoing natural-water connection, but rainfall, evaporation, seepage and makeup water still matter. Small persistent fluxes alter long-term inventory, and different reservoir areas produce unequal losses. Separating weather exchange from machine transfers allows the scheduling ledger to diagnose the actual source of a storage discrepancy rather than assign every change to pumping. || 假設兩庫合計水面1000000m²、日蒸發0.004m，日損失4000m³；未計降雨與滲漏，不可稱封閉循環零耗水。~Assume combined surface area1000000m² and daily evaporation0.004m. Loss is4000m³/day, excluding rain and seepage; closed-loop does not mean zero water use. || 將降雨蒸發深度乘當日水面積，核對毫米與米及每日與每秒的換算。把滲漏、補水與量測零漂分開追蹤，以多日總量閉合而非單一水位點判斷是否存在持續庫存損失。~Multiply weather depths by contemporaneous surface area and verify millimeter-to-meter and daily-to-second conversions. Track seepage, makeup and sensor drift separately, using multi-day volume closure rather than one level reading to identify persistent inventory loss. || 將蒸發列成每次抽水循環的固定損失會讓結果隨排程次數虛增，忽略面積變化又會產生季節偏差。漏水與零漂混在一起時，錯誤補水判斷也可能擴大。~Treating evaporation as a fixed loss per pumping cycle makes it grow artificially with cycling frequency. Ignoring area variation adds seasonal bias, while confusing leakage with sensor drift can lead to inappropriate makeup estimates. || 封閉循環抽蓄完全不會受到降雨、蒸發或滲漏影響。~Closed-loop pumped storage is completely unaffected by rainfall, evaporation or seepage.
期末庫存與預留~Terminal inventory and reservation || 有限時域排程若不約束期末庫存，會把最後一刻耗盡上庫當成最佳結果，卻把下一日需求隱藏起來。預留可用水量與電能不能直接互換，必須考慮當時水頭和可用機組；應明列預留目的以及何時可以釋放，避免重複承諾同一份水。~A finite-horizon schedule without a terminal-storage constraint can favor emptying the upper reservoir at the last instant while hiding the following day’s need. Reserved water is not automatically reserved electrical energy because head and unit availability matter. State the purpose and release condition of each reservation to avoid committing the same inventory to multiple services. || 假設上庫可用800000m³，其中預留200000m³，其他條件允許時最多移出600000m³；兩項服務不能重複使用同一預留量。~Assume upper usable storage800000m³ with200000m³ reserved. At most600000m³ is transferable if other constraints permit, without double-allocating the reservation. || 把期末目標、預留用途與可釋放條件寫成獨立約束，逐步檢查同一水量是否被重複計入不同服務。將預報入流減少的情境再跑一次，報告未滿足需求而非讓計算暗中借用下一日庫存。~Express terminal targets, reserved services and release conditions as separate constraints and check inventory is not allocated twice. Repeat the schedule with reduced forecast inflow and report unmet demand rather than silently borrowing storage intended for the next day. || 完美預報假設會讓預留不足的方案看似可行，期末缺水又會被截斷時域隱藏。若兩個備援服務同時到來，共用一份預留水量的承諾便無法全部履行。~Perfect-forecast assumptions can make inadequate reserves seem feasible, while horizon truncation hides terminal shortage. If two reserve services arrive together, promises backed by the same water inventory cannot both be fulfilled. || 同一份預留水量可以同時保證任意多個獨立備援服務。~The same reserved water can simultaneously guarantee any number of independent backup services.
''')
META['b258']=dict(sources=['pumped-storage','psh-guide','bath-storage','elbert-storage','hydro-structures'],vendorSources=['pumped-storage','hydro-structures'],related=['b259','b260'],summary=pair('本課從上下庫逐時水量守恆開始，將庫容、水位、淨水頭、機組效率與電能連成可追溯帳本。十個單元分別處理抽水與發電方向、往返效率、可用時數、爬坡積分、天氣損失和期末預留，要求學徒在每個時間步查兩庫限制，並把慢速排程與快速水錘模型分開驗證。','Starting with paired-reservoir conservation, this course connects storage, level, net head, machine efficiency and energy in a traceable ledger. Ten units distinguish pumping and generation, cycle efficiency, duration, ramps, weather exchange and terminal reserves. Apprentices check both reservoirs at every step and verify slow scheduling separately from rapid waterway transients.'),history=pair('抽蓄的核心是先用電把水提升，再於需要時讓水回流發電，並非生產額外能量。巴斯郡業主記錄電站於一九八五年十二月商轉，墾務局埃爾伯特資料提供另一組真實抽蓄配置。本課不把兩站的營運參數混成通用模板。美國陸軍工兵團二〇〇八年更新水力電廠結構手冊；能源部二〇二二年的介紹則記錄國家實驗室指南及二〇二一年工具發布，提醒分析服務、時間邊界和權衡。下列數值全為獨立教學假設，不是任一電站的調度表。','Pumped storage first uses electricity to lift water and later recovers part of that energy; it does not create additional energy. The Bath County owner records commercial operation in December1985, while Reclamation’s Mt. Elbert data supplies another genuine configuration. Their operating parameters are not blended into a universal template. USACE updated hydroelectric structural guidance in2008, and DOE’s2022 article describes laboratory valuation guidance and the tool released in2021, emphasizing services, boundaries and tradeoffs. Every numerical example below is an independent teaching assumption rather than a plant schedule.'),example=pair('原創水頭敏感度：固定流量100m³/s、總發電效率0.90與密度1000kg/m³，淨水頭385m時功率為339.9165MW。如果其他假設維持不變而淨水頭提高10%至423.5m，功率為373.90815MW，正好提高10%。這不表示真實機組可突破額定容量，也不表示水頭提高後效率必然固定。學徒應把新工況放回效率曲線、流量與電氣容量限制，再沿上下庫水位歷時積分電能。若要求固定功率，流量會反向調整，不能仍用原先水量帳本，且需重新檢查管路瞬態與進水條件。','Original head sensitivity: with discharge100m³/s, overall generating efficiency0.90 and density1000kg/m³ fixed, net head385m gives339.9165MW. Raising net head by10% to423.5m while holding the other assumptions fixed gives373.90815MW, exactly10% higher. This does not permit exceeding nameplate capacity or establish constant real-machine efficiency at the new head. Place the new condition on the efficiency map and check discharge and electrical limits before integrating energy along the reservoir-level histories. If constant power is required instead, discharge changes inversely; the original water ledger no longer applies and transient and intake conditions must be checked again.'),timeline=[('1985','巴斯郡抽蓄電站十二月開始商業運轉~Bath County begins commercial operation in December'),('2008','工兵團更新水力電廠結構規劃設計手冊~USACE updates hydroelectric power-plant structural planning guidance'),('2021','國家實驗室抽蓄價值評估工具十一月發布~National-laboratory pumped-storage valuation tool launches in November')],codes=['水力電廠結構規劃與設計EM1110-2-3001~EM1110-2-3001 hydroelectric structural planning and design','抽蓄價值評估指南與十五步分析框架~Pumped Storage Valuation Guidebook and fifteen-step framework'],landmarks=['巴斯郡電站：上下庫抽蓄配置~Bath County station: paired-reservoir pumped storage','埃爾伯特電站：抽蓄機組比較~Mt. Elbert plant: pumped-storage configuration comparison'],place=dict(name='巴斯郡公共電站背景區~Bath County public plant context',country='美國~United States',lat=38.209,lng=-79.800,query='Bath County Pumped Storage Station Virginia'))

source('steel-penstocks','焊接鋼壓力管專論','Engineering Monograph3: Welded Steel Penstocks','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/hydraulics_lab/pubs/manuals_monographs.html','官方清單確認一九四九年專論及一九六六年修訂；用作鋼管荷載與支承背景，不將歷史方法當成現場驗收結論。','Official list confirms the1949 monograph and1966 revision; used for steel-pipe load and support context, not as a current field acceptance decision.','Opened turn238view0, line37, title and dates.')
source('penstock-inspection','鋼壓力管與壓力渠道檢查','FIST2-8 Inspection of Steel Penstocks and Pressure Conduits','US Bureau of Reclamation','https://www.usbr.gov/power/data/fist_pub.html','官方清單列二〇二二年八月鋼管檢查手冊，支持厚度、支承及可追溯維護資料的查核；數值許用應力未由此推定。','Official list dates the steel-conduit inspection manual to August2022, supporting traceable thickness, support and maintenance evidence; no allowable stress is inferred.','Opened turn240view2, line39; edition title/date confirmed.')
source('eklutna-history','埃克盧特納鋼管與調壓設施歷史','Eklutna Project construction history','US Bureau of Reclamation','https://www.usbr.gov/history/eklutna.html','官方歷史描述包覆鋼管、混凝土錨塊與調壓井施工；作真實配置案例，不把本課尺寸或瞬態參數當成其設計資料。','Official history describes encased steel penstocks, concrete anchor blocks and surge-tank construction; synthetic dimensions and transient parameters are not site design data.','Opened turn238view2 and found turn248view1 lines99–106: surge excavation1953, lining1954, anchor block and encased penstock.')
compact('b259','追蹤壓力、重量與溫度荷載如何經鋼管傳到錨塊支承~Trace pressure, gravity and thermal loads through penstocks into anchors and supports',r'''
環向薄膜應力~Circumferential membrane stress || 圓管內壓使管壁承受環向拉力，薄壁公式可先估量級，但只描述遠離支承與接頭的膜應力。焊接缺陷、橢圓化和局部加勁會改變應力分布，外壓失穩又是另一機制；必須先辨明幾何與壓力方向，不能把一個平均值當成整根鋼管安全證明。~Internal pressure creates circumferential tension, and a thin-wall estimate gives membrane stress away from supports and connections. Weld defects, ovality and local stiffening alter the distribution, while external-pressure buckling is a different mechanism. Establish geometry and pressure direction before treating a mean stress as evidence about the entire penstock’s structural behavior. || 假設薄壁圓管表壓p=2MPa、內徑D=2m、均勻壁厚t=0.020m，σh=pD/(2t)=100MPa；未含局部彎曲。~Assume thin circular pipe gauge pressure2MPa, inner diameter2m and uniform thickness0.020m. Hoopσh=pD/(2t)=100MPa, excluding local bending. || 畫半圓自由體平衡，核對內徑、有效厚度及表壓使用方式，並計算厚徑比。將支座、分岔、焊縫與變厚位置另列局部分析範圍，保留材料和厚度量測資料而不只比較單一應力數字。~Draw a half-cylinder equilibrium diagram, checking inner diameter, effective thickness and gauge pressure and calculating thickness ratio. Flag supports, branches, welds and thickness transitions for local analysis and retain material and measurement evidence rather than comparing only one stress value. || 局部腐蝕孔與焊縫缺陷可能控制承載，平均厚度會掩蓋最弱位置。空管外部地下水形成的壓力方向相反，不能把內壓拉力公式直接用來證明抗屈曲能力。~Local pits and weld flaws may govern strength while mean thickness hides the weakest region. Groundwater acting on a drained pipe reverses pressure direction, so an internal-tension formula does not establish external-buckling resistance. || 平均環向應力低於某個數字就能證明所有支座與焊縫都安全。~A low average hoop stress proves every support and weld is structurally acceptable.
封閉端軸向作用~Closed-end axial action || 封閉端的壓力合力需要由管壁或其他結構路徑平衡，軸向應力取決於端部約束與伸縮接頭。對可自由伸長的封閉薄壁管可以直接用端面平衡，但固定管線、泊松變形和錨塊分擔會改變答案；不能將教學圓筒公式無條件貼到埋設管。~Pressure on a closed end must be balanced through the wall or another structural path. Axial stress depends on end restraint and expansion joints. End equilibrium applies directly to a freely extending closed thin cylinder, but fixed pipelines, Poisson effects and anchor load sharing change that answer and require a consistent boundary model. || 假設封閉端且軸向無外部約束，p=2MPa、D=2m、t=0.020m，σa=pD/(4t)=50MPa；固定管段需另建約束模型。~Assume closed ends and no external axial restraint, withp=2MPa,D=2m,t=0.020m. Axialσa=pD/(4t)=50MPa; restrained segments require another model. || 沿管線標出固定點、滑動點與伸縮接頭，畫端部壓力進入管壁或錨塊的路徑。分開列自由伸長與完全固定的邊界情境，核對管壁軸力與外部反力是否共同滿足整體平衡。~Map fixed points, sliding supports and expansion joints and trace end pressure into wall or anchor reactions. Separate free-extension and fixed-boundary cases, checking that wall force and external reactions together satisfy equilibrium of the complete selected pipe segment. || 若壓力推力已被錨塊承擔又完整加到管壁，會重複荷載；反之兩邊都忽略則遺失力。約束不清時即使公式算得精準，軸向設計仍可能根本錯位。~Assigning full pressure thrust to both wall and anchor double-counts load, while assigning it to neither loses equilibrium. Precise arithmetic cannot repair an axial design based on an undefined or inconsistent restraint condition. || 封閉端公式可直接代表任何固定、埋設或帶伸縮接頭管線的軸向應力。~The closed-end formula directly gives axial stress for every fixed, buried or expansion-jointed pipeline.
彎管壓力向量~Elbow pressure vectors || 管線轉向時兩端壓力力的向量差形成彎管合力，不能只把壓力乘單一截面就當成所有方向的錨定荷載。動量變化、水重、管重與支承反力還要在完整自由體另列；等壓靜態示例只幫助確認角度與方向，不代表實際組合荷載。~A change in direction produces a resultant from the pressure-force vectors at an elbow’s ends. Pressure times one area alone does not describe every anchorage component. Momentum flux, water and pipe weight and support reactions belong in the full free body; an equal-pressure static example checks orientation rather than replacing the actual load combination. || 假設等徑2m、兩端表壓2MPa、轉角90°且忽略動量及重量，F=2pA sin45°=8.8858MN，方向沿兩壓力向量合成。~Assume diameter2m, equal gauge pressure2MPa and90° turn, neglecting momentum and weight. F=2pA sin45°=8.8858MN along the pressure-vector resultant. || 在平面圖畫兩端法向及壓力箭頭，用分量法和向量模長各算一次，確認轉角定義。再加入流速動量、重力與管壁傳力，標註哪些項已由相鄰固定點吸收，避免重複或漏列。~Draw end normals and pressure arrows, calculating both components and resultant magnitude with a stated turn angle. Then add momentum, gravity and wall-force paths, marking loads transferred to adjacent fixed points to prevent omission or double counting. || 把九十度誤認為兩箭頭之夾角可能改變符號，錯把單端推力當合力則低估需求。真實彎管若有不同管徑或壓力，等壓等面積捷徑便不再成立。~Confusing pipe turn with arrow orientation can reverse signs, and using one end thrust understates the resultant. Unequal diameters or pressures invalidate the equal-area, equal-pressure shortcut even if the elbow angle is unchanged. || 彎管的錨定合力永遠等於一端壓力乘截面積而與轉角無關。~Elbow anchorage force always equals one end pressure times area, regardless of the turn angle.
自由熱伸長~Free thermal expansion || 暴露鋼管溫度改變會產生自由伸縮，支座與接頭必須提供與模型一致的運動空間。水溫、日照及安裝時溫度不必相同，沿線不均勻加熱還會造成彎曲；先算無約束伸長有助於辨認需求，但不能把這個位移視為固定管段也會自由發生。~Exposed steel changes length with temperature, so supports and joints must permit the motion assumed by the model. Water temperature, solar heating and erection temperature differ, and nonuniform heating can induce bending. Computing unconstrained extension identifies movement demand without implying that a fixed segment can actually undergo the same free displacement. || 假設均勻升溫30°C、α=12×10⁻⁶/°C、自由長度100m，ΔL=αLΔT=0.036m；未含溫度梯度與約束。~Assume uniform warming30°C, expansion coefficient12×10⁻⁶/°C and free length100m. ΔL=0.036m, excluding temperature gradients and restraint. || 以安裝溫度為基準記錄季節溫度範圍，核對自由長度兩端是否真能移動。將預測位移與接頭行程及滑動支座位置對照，並檢查沿管溫差是否需要分段積分而非使用單一平均溫度。~Reference the seasonal range to erection temperature and verify both ends of the free length can move as assumed. Compare predicted displacement with joint travel and sliding-support position, and assess whether varying temperature requires integration along separate pipe segments. || 接頭卡死會把本來的位移需求轉成內力，支座滑到行程端也會改變邊界。只用水溫估暴露管線，可能漏掉日照引起的上下壁溫差和彎曲。~A seized joint converts movement demand into internal force, and a support reaching its travel stop changes the boundary. Water temperature alone may miss solar differences between upper and lower pipe walls and associated bending. || 算出自由伸長後就可假定任何固定錨塊之間都會發生同樣位移。~Calculated free expansion occurs unchanged between any pair of fixed anchor blocks.
完全約束熱應力~Fully restrained thermal stress || 熱伸縮被阻止時會產生軸向內力，其大小取決於管壁、錨塊與地基共同剛度。完全固定只是一個清楚的極端情境，實際支座滑移或混凝土變形會重新分配力；溫度循環還可能形成疲勞，因此不能僅檢查一次最大升溫的平均應力。~Prevented thermal movement creates axial force governed by combined pipe, anchor and foundation stiffness. Full restraint is a defined limiting case; sliding and concrete deformation redistribute force in practice. Temperature cycling can also contribute to fatigue, so a single maximum-warming stress does not characterize the complete history or the response of every connection. || 假設軸向完全固定、均勻升溫30°C、E=200GPa、α=12×10⁻⁶/°C，壓應力幅值EαΔT=72MPa，限線彈性。~Assume full axial restraint, uniform warming30°C,E=200GPa andα=12×10⁻⁶/°C. Compressive stress magnitudeEαΔT=72MPa in the linear-elastic idealization. || 先說明固定是位移約束還是高剛度彈簧，分開計算完全自由與固定兩端情境。核對升溫造成壓縮、降溫造成拉伸的符號，再與壓力軸力及支承變形組合，保留各荷載的時間關係。~State whether restraint is a prescribed displacement or a stiff spring and compare free and fixed limiting cases. Check warming-compression and cooling-tension signs, then combine pressure force and support deformation while retaining the timing of each load contribution. || 忽略錨塊位移可能高估平均熱力，但忽略局部卡阻又可能低估局部需求。若進入降伏或接頭滑移，線性完全固定公式便不能描述卸載後的殘餘變形。~Ignoring anchor movement can overstate average thermal force, while missing local seizure understates local demand. Yielding or joint slip invalidates the linear fully restrained model for residual deformation after unloading. || 完全固定熱應力公式能直接描述任何降伏、滑移與殘餘變形。~The fully restrained elastic formula directly describes yielding, sliding and all residual deformation.
管體與充水重量~Pipe and contained-water weight || 支承承受的不只有鋼殼重量，充水狀態通常還有大量水重，空管與滿管因而是不同荷載情境。斜管重量要分解到管軸與法向，包覆混凝土或外部浮力也需要獨立列項；不能把管內水的體積當成鋼材體積或忽略單位長度的定義。~Supports carry both steel and contained water, making empty and full conditions distinct load cases. Inclined weight must be resolved axially and normally, while encasement or external buoyancy requires separate terms. Internal water volume is not steel volume, and the reference unit length must remain explicit before reactions are distributed between supports. || 假設水平滿管內徑2m、外徑2.04m、鋼密度7850及水1000kg/m³，w=g[7850π(2.04²−2²)/4+1000π]=40.593kN/m。~Assume a horizontal full pipe with inner diameter2m, outer2.04m, steel density7850 and water1000kg/m³. Combined distributed weight is40.593kN/m. || 分別畫鋼環與水圓截面，以密度乘面積再乘重力計單位長度荷載，核對外徑減內徑的平方順序。比較空管和滿管，再按斜率分解重量，將外部水壓或混凝土支承另列清楚。~Draw steel annulus and water disk separately, multiplying density by area and gravity for each unit-length load. Check squared diameters, compare empty and full cases, resolve inclined weight and separately identify external pressure and any concrete support contribution. || 漏算水重會低估反力，將壁厚直接當成截面面積則量綱已錯。外部地下水作用於空管時可能有淨上浮，與滿管向下重量情境不能混為同一驗算。~Omitting water understates reactions, while using thickness as area is dimensionally wrong. Groundwater can produce net uplift on an empty conduit, which must not be conflated with the downward weight of the full-pipe case. || 管線支座只需要承受鋼材自重而不必考慮管內水重。~Penstock supports carry only the steel’s own weight and need not consider contained water.
跨距與梁式反力~Span and beam reactions || 相鄰支座之間的管段可先用梁模型理解整體彎矩與反力，但鞍座附近的環向彎曲和殼體橢圓化不是梁公式能描述。連續支承、不同沉陷與壓力剛化也可能改變分配，因此必須把全跨分析與局部殼體查核分開，同時保持一致荷載路徑。~A beam idealization helps interpret span moment and reactions, but it does not resolve circumferential bending and shell ovality near saddles. Continuity, differential settlement and pressure effects can change load distribution. Separate global span response from local shell assessment while keeping a consistent load path between the two analytical representations. || 假設簡支跨距10m、均布荷載40kN/m，Mmax=wL²/8=500kNm，兩端反力各200kN；未評估鞍座局部殼應力。~Assume a simply supported10m span under uniform40kN/m. Maximum moment500kNm and reactions200kN each exclude local saddle shell stresses. || 畫清支座轉動及平移自由度，以反力總和檢查荷載平衡，再比較連續梁或支座沉陷情境。把全跨彎矩傳入管壁應力分析，並另設鞍座接觸角、加勁環及局部變形檢核項目。~Define support rotational and translational freedoms and check reaction sum against total load, then compare continuity and settlement cases. Carry span moment into wall analysis while separately assessing saddle contact angle, stiffening rings and local shell distortion. || 簡支假設若不符合實際固定程度會改變彎矩位置，單看跨中最大值也可能漏掉支座負彎矩。管殼局部壓扁即使總體梁應力不高，仍可能控制支承細節。~An incorrect simple-support assumption shifts moment distribution, and focusing on midspan misses support moments. Local flattening of the shell can govern saddle details even when the global beam stress appears modest. || 梁式跨中彎矩通過檢查就等於鞍座周圍殼體應力也已驗證。~A satisfactory beam midspan moment automatically verifies shell stresses around every saddle.
滑動摩擦與固定點~Sliding friction and fixed points || 滑動支座的目的通常是容許伸縮，但摩擦仍會把部分軸力傳到固定點。靜摩擦上限與實際動摩擦力不同，接觸壓力、鏽蝕及潤滑會改變參數；不能用名義摩擦係數保證永遠能滑動，也不能把所有支座最大摩擦同時同向當成必然情況。~Sliding supports permit movement while friction still transfers axial force to fixed points. Limiting static friction differs from actual sliding resistance, and contact pressure, corrosion and lubrication change the parameter. A nominal coefficient does not guarantee motion, nor does it establish that every support simultaneously mobilizes its maximum resistance in the same direction. || 假設接觸法向力400kN、庫侖摩擦係數0.15，摩擦上限μN=60kN；靜止時實際摩擦可小於此值。~Assume contact normal force400kN and Coulomb coefficient0.15. Limiting frictionμN=60kN; actual static friction may be smaller than this bound. || 先判斷支座處於黏著還是滑動狀態，對照位移紀錄、接觸面狀況與法向荷載。用摩擦上下界做反力敏感度，逐段檢查軸向平衡，不把極限值當成每個時刻都存在的固定外力。~Determine sticking or sliding from movement records, contact condition and normal load. Explore plausible friction bounds in reaction sensitivity and check axial equilibrium segment by segment rather than treating the limit as a constant force acting at all times. || 支座鏽死時原先的滑動邊界可能變成固定點，熱力路徑隨之改變。摩擦方向也會在升降溫時反轉，忽略歷時便可能錯算錨塊反力及接頭行程。~A corroded seized support may become a fixed point and redirect thermal force. Friction reverses with movement direction, so neglecting the sequence can misstate anchor reaction and expansion-joint travel during temperature cycles. || 靜止滑動支座的實際摩擦力在任何時刻都必定等於摩擦係數乘法向力。~Actual friction at a stationary sliding support always equals coefficient times normal force.
錨塊基底平均壓力~Anchor base average pressure || 錨塊把管線荷載傳到地基，但平均基底壓力只適用於假設的接觸狀態，不能單獨評估抗滑或抗傾覆。偏心、基底張開及地基不均勻會改變壓力分布；應把力、力矩、排水及基礎剛度放在同一自由體中，再決定簡化均壓是否合理。~An anchor transfers pipeline loads to the foundation, but average base pressure depends on the assumed contact state and does not establish sliding or overturning resistance. Eccentricity, uplifted contact and variable ground stiffness change the distribution. Include force, moment, drainage and foundation stiffness before deciding whether a uniform-pressure idealization is defensible. || 假設中心向下合力2MN作用於全接觸基底4m²，q=N/A=500kPa；不是地基允許承壓值且未計偏心。~Assume a centered downward resultant2MN on a fully contacting4m² base. Averageq=500kPa is not allowable bearing pressure and excludes eccentricity. || 對錨塊整體列垂直力與力矩平衡，核對是否有地下水上浮或水平管推力造成偏心。用接觸範圍和地基資料判斷均壓假設，再分別查抗滑、傾覆、沉陷與混凝土局部受力。~Check vertical-force and moment equilibrium, including groundwater uplift and eccentricity from horizontal pipe thrust. Use contact and ground evidence to assess uniform pressure, then examine sliding, overturning, settlement and local concrete actions as separate mechanisms. || 將五百千帕誤寫成地基承載能力會倒置需求與抗力，偏心時平均值又會掩蓋最大壓力。基底部分脫離後，仍以原面積均分會低估剩餘接觸區需求。~Calling500kPa a foundation capacity reverses demand and resistance, while average pressure hides peaks under eccentricity. After partial loss of contact, dividing by the original area understates demand on the remaining bearing region. || 基底平均壓力算得出來就代表錨塊抗滑、傾覆與地基承載均已合格。~Calculating average base pressure proves acceptable sliding, overturning and foundation capacity.
減薄與剩餘厚度~Wall loss and remaining thickness || 腐蝕造成的壁厚減少會提高相同內壓下的膜應力，但均勻減薄只是一種理想情境，局部坑蝕與裂縫需要不同評估。厚度量測的網格與位置應可追溯，不能用最容易量到的一點代表整段；塗層良好也不等於內外壁都沒有缺陷。~Wall loss raises membrane stress at the same internal pressure, but uniform thinning is only one idealization and pits or cracks require different assessment. Measurement grids and locations must be traceable; an easily accessible point cannot represent the whole segment. A sound coating also does not prove the absence of defects on either surface. || 假設壓力及直徑不變、均勻厚度20mm降至18mm，環向應力100×20/18=111.11MPa，增加11.11%；未評局部坑蝕。~Assume unchanged pressure and diameter with uniform thickness falling20 to18mm. Hoop stress rises100×20/18=111.11MPa, an11.11% increase, excluding pitting assessment. || 將厚度圖與原始製造、焊縫和歷次量測對位，確認儀器校正與塗層修正。分辨均勻減薄、局部坑蝕和裂紋，再用相應方法評估，不以平均厚度或外觀照片取代最弱區域的證據。~Register thickness maps with fabrication, weld and prior inspection records, checking calibration and coating corrections. Distinguish uniform loss, pits and cracks and apply appropriate assessment methods rather than substituting average thickness or appearance for evidence at the weakest region. || 量測點偏離最薄區會得到假安心，腐蝕速率也未必長期固定。單靠線性外推厚度可能漏掉局部加速或裂紋擴展，應保留測值不確定度與機制分類。~Measurements missing the thinnest area give false reassurance, and corrosion rate need not remain constant. Linear thickness extrapolation can miss local acceleration or crack growth, requiring retained uncertainty and a clear classification of damage mechanisms. || 壁厚減少百分之十時膜應力一定也只增加百分之十且不需檢查局部缺陷。~A ten-percent thickness loss raises stress by exactly ten percent and removes any need to check local defects.
''')
META['b259']=dict(sources=['steel-penstocks','penstock-inspection','hoover-history','eklutna-history','hydro-structures'],vendorSources=['steel-penstocks','hydro-structures'],related=['b258','b260'],summary=pair('本課用完整荷載路徑理解壓力鋼管，而不只套一條薄壁應力公式。十個單元依序分辨環向與軸向力、彎管向量、熱伸縮、滿管重量、跨距反力、滑動摩擦、錨塊基底及減薄檢查，要求每個簡化模型先畫自由體與邊界，再說明未包含的局部殼體、基礎與疲勞問題。','This course follows the complete penstock load path rather than relying on one thin-wall formula. Ten units distinguish hoop and axial action, elbow vectors, thermal movement, full-pipe weight, span reactions, friction, anchor bearing and wall loss. Each simplified model begins with a free body and boundaries and identifies excluded shell, foundation and fatigue behavior.'),history=pair('大型水力工程的鋼管需要把水壓與重量可靠地送到支承和地基，設計與後續檢查因此相互依賴。胡佛壩官方歷史描述壓力鋼管和錨定工程；埃克盧特納資料則記錄包覆鋼管、混凝土錨塊與地基鋼樁，提供不同配置的比較。墾務局鋼壓力管專論於一九四九年出版並在一九六六年修訂，二〇二二年八月的檢查手冊另強調維護證據。本課不把歷史案例的存在當成合成尺寸可直接施工的理由，亦不把舊專論替代場址適用的設計要求。','Large hydropower penstocks must transfer pressure and weight into supports and foundations, making design and inspection interdependent. Hoover’s official history describes penstocks and anchorage, while Eklutna documents encased steel, concrete anchor blocks and foundation piles as a contrasting configuration. Reclamation’s steel-penstock monograph was published in1949 and revised in1966; the August2022 inspection manual supplies a separate maintenance reference. These historical examples do not authorize construction from synthetic dimensions, and an older monograph is not substituted for applicable site design requirements.'),example=pair('原創壓力敏感度：薄壁圓管內徑2m、均勻厚度0.020m，表壓2MPa時環向膜應力為100MPa。如果保持幾何及線彈性假設而壓力增加10%至2.2MPa，應力增為110MPa，增加10%。此線性關係不能證明材料、焊縫或支座仍有足夠餘量。學徒應再列端部軸力、彎管壓力向量和錨塊需求如何同時增加，並檢查壓力峰值是否出自水錘。若發生減薄、塑性或外壓屈曲，原先模型邊界已改變，不能以這個單一百分比概括所有失效機制。','Original pressure sensitivity: a thin circular pipe with inner diameter2m and uniform thickness0.020m has hoop membrane stress100MPa at gauge pressure2MPa. Holding geometry and linear-elastic assumptions fixed while increasing pressure10% to2.2MPa raises stress to110MPa, also10%. That proportionality does not demonstrate adequate material, weld or support margin. Apprentices should also trace increased end force, elbow pressure vectors and anchor demands and determine whether the peak is a water-hammer transient. Wall loss, plasticity or external-pressure buckling changes the original model boundary, so one percentage cannot summarize every failure mechanism.'),timeline=[('1949','墾務局出版焊接鋼壓力管工程專論~Reclamation publishes its welded steel penstocks engineering monograph'),('1966','焊接鋼壓力管專論完成修訂版~Welded steel penstocks monograph receives its revised edition'),('2022','八月版鋼壓力管與壓力渠道檢查手冊列入官方清單~August steel penstock inspection manual appears in official listing')],codes=['工程專論第三號焊接鋼壓力管~Engineering Monograph3 Welded Steel Penstocks','FIST2-8鋼壓力管與壓力渠道檢查~FIST2-8 Inspection of Steel Penstocks and Pressure Conduits'],landmarks=['胡佛壩：鋼管錨定配置比較~Hoover Dam: penstock anchorage configuration comparison','埃克盧特納：包覆鋼管及錨塊~Eklutna: encased penstock and anchor block'],place=dict(name='埃克盧特納公共工程背景區~Eklutna public project context',country='美國~United States',lat=61.467,lng=-149.150,query='Eklutna Power Plant Alaska'))

source('coachella-surge','科切拉配水管網湧浪控制專論','Engineering Monograph17: Surge Control on the Coachella Pipe Distribution System','US Bureau of Reclamation','https://www.usbr.gov/tsc/techreferences/hydraulics_lab/pubs/manuals_monographs.html','官方目錄確認一九五四年配水管網湧浪控制專論；與水力電廠調壓井比較邊界，不宣稱兩系統可沿用同一控制參數。','Official catalogue confirms the1954 distribution-system surge-control monograph; its boundaries are compared with hydropower shafts without transferring operating parameters.','Opened turn238view0 line51; PDF link exists but retrieval failed turn259view2, so scope limited to verified catalogue title/date.')
source('coachella-project','全美運河與科切拉配水工程','All-American Canal and Coachella distribution system','US Bureau of Reclamation','https://www.usbr.gov/projects/index.php?id=514&lang=en','官方歷史記錄科切拉配水工程與一九五四年完成背景；僅定位管網比較案例，不將開渠與壓力管瞬態混為相同方程。','Official history records the Coachella distribution works and1954 completion context; used to locate the network comparison, not equate open-channel and pressure-pipe transients.','Opened turn259view0 lines48–50. Historical page contains old current-condition statements which are not reused.')
compact('b260','分開快速彈性壓力波與慢速調壓井振盪並檢查相互作用~Distinguish rapid elastic pressure waves from slower surge-shaft oscillations and check their interaction',r'''
彈性波速與管壁~Elastic wave speed and pipe wall || 水錘傳播速度同時受水可壓縮性與管壁變形影響，不是把水視為完全剛性就能描述。管壁約束、材料模數與含氣量會改變波速，薄壁圓管公式需要明列修正係數；用一個假設波速計算的壓力峰值，必須隨參數不確定度重新檢查。~Water-hammer propagation depends on both fluid compressibility and pipe-wall deformation, so a rigid-water assumption cannot describe the wave. Restraint, material modulus and gas content affect celerity, and the thin circular-pipe expression requires an explicit restraint factor. Pressure estimates made with one assumed speed must be reconsidered when that parameter is uncertain. || 假設K=2.2GPa、ρ=1000kg/m³、E=200GPa、D=2m、t=0.02m，管壁修正係數取1，a=√[K/ρ/(1+KD/Et)]=1023.53m/s。~AssumeK=2.2GPa,ρ=1000kg/m³,E=200GPa,D=2m,t=0.02m and wall-restraint factor1. Wave speeda=√[K/ρ/(1+KD/Et)]=1023.53m/s for this idealization. || 記錄流體與管材模數、厚度和軸向約束來源，確認管壁修正係數是否適用。用量測波到達時間比較估計波速，再測試含氣或厚度變動的敏感度，不藉調整波速掩蓋錯誤邊界。~Document fluid and wall moduli, thickness and axial-restraint evidence and check the chosen correction factor. Compare predicted speed with measured wave arrival, then test gas-content and wall variations rather than tuning celerity to conceal an incorrect boundary condition. || 少量夾氣可能顯著改變可壓縮性，複合管或厚壁管也不符合簡式。把鋼材彈性模數當水體積模數，或漏掉帕與吉帕換算，會使壓力與時間尺度同時失真。~Entrained gas changes compressibility, and composite or thick walls fall outside this simple expression. Substituting steel modulus for water bulk modulus or confusing pascals and gigapascals distorts both pressure magnitude and wave timing. || 水錘波速只由水決定而完全不受管壁、約束或夾氣影響。~Water-hammer wave speed depends only on water and never on pipe walls, restraint or entrained gas.
往返時間與邊界~Round-trip time and boundaries || 閥門動作與壓力波往返時間的比較，決定反射是否已在動作期間返回控制點。最簡水庫管閥系統只有一條明確路徑，但分岔、調壓井與不同波速管段會產生多重反射；時間尺度只是辨識模型的入口，不能據此直接宣布某個關閉時間安全。~Comparing actuator duration with wave round-trip time shows whether a reflection returns during the action. A reservoir-pipe-valve system has one simple path, whereas branches, shafts and segments with different celerity create multiple reflections. This time scale helps select the analysis and does not by itself approve a particular valve-closing duration. || 假設均勻管長L=1000m、波速a=1000m/s，往返時間2L/a=2s；只代表此單一路徑，不是允許關閉時間。~Assume uniform pipe length1000m and celerity1000m/s. Round-trip2L/a=2s describes only this path, not an allowable closing time. || 在系統圖標出反射邊界及每段長度波速，逐段累加單程時間，再與閥門實際流量變化歷時比較。遇到分岔或調壓接點就建立多路徑時間表，不能只取地圖上兩點直線距離。~Mark reflecting boundaries and each segment’s length and celerity, sum one-way travel times and compare with actual discharge-change histories. For branches and shaft junctions construct a multiple-path timing table instead of using the straight-line distance between map locations. || 將單程時間當往返時間會改變快速與慢速的分類，忽略分岔反射則可能漏掉疊加峰值。即使動作很慢，長時間水位振盪或控制不穩定仍可能存在。~Confusing one-way with round-trip time changes the rapid-action classification, while omitted branch reflections can hide superposed peaks. Slow actuation can still produce long-period level oscillations or unstable control interactions. || 閥門動作時間大於單一往返時間就一定不會出現任何危險壓力。~An actuator duration longer than one round-trip time guarantees the absence of dangerous pressure.
快速變速壓力增量~Rapid velocity-change pressure || 單相彈性管中的突然流速變化會形成壓力波，焦科夫斯基關係估第一個波前的壓力增量。它不是整段歷時的通用最大值，反射疊加、氣穴與控制器仍可能改變結果；應先區分增量和原有靜壓，再檢查是否仍滿足單相及快速動作假設。~A rapid velocity change in a single-phase elastic conduit generates a pressure wave, with the Joukowsky relation estimating the first-front increment. It is not a universal maximum for the entire history: reflections, cavities and control behavior can alter the result. Distinguish this increment from initial pressure and verify both the rapid-action and single-phase assumptions. || 假設ρ=1000kg/m³、a=1000m/s，0.5s內減速1m/s且小於2s往返，Δp=ρaΔV=1MPa，ΔH=101.94m。~Assumeρ=1000kg/m³,a=1000m/s and velocity reduction1m/s in0.5s, shorter than2s round-trip. Initial pressure increment1MPa corresponds to101.94m head. || 明列初始壓力與增量的符號，核對減速與壓力上升的傳播方向。將第一波預估和完整瞬態歷時比較，另查後續反射最低壓力、局部空化及機組反應，不把首波算式視為完整包絡。~State initial pressure and increment signs and verify the propagation direction associated with deceleration. Compare the first-wave estimate with a full transient history and separately examine reflected minima, local cavitation and machine response rather than treating the first front as the complete envelope. || 把壓力增量當成總壓力會漏掉原有水頭，慢關閉時套完整瞬降公式又可能錯估反應。若發生水柱分離，重新閉合壓力不能靠原單相首波關係完整描述。~Treating the increment as total pressure omits the initial head, while applying instantaneous reduction to slow closure misrepresents the response. Column separation and rejoining cannot be fully described by the original single-phase first-wave relation. || 焦科夫斯基首波增量就是所有反射與氣穴情境下的完整最大總壓力。~The Joukowsky first-wave increment is the complete maximum total pressure for every reflection and cavitation scenario.
井內連續方程~Continuity within the shaft || 調壓井提供暫時儲水空間，管內來水與下游取水不相等時便改變井內水位。這個體積平衡不需要先求水錘峰值，但流量差本身會隨水位與管內慣性變化；固定面積只能用在井身相應區段，不能把瞬時上升速率無限制外推。~A surge shaft temporarily stores the difference between conduit inflow and downstream demand. Volume continuity can be written before solving the pressure-wave peak, but that flow difference evolves with level and conduit inertia. Constant area applies only within the relevant shaft segment, and an instantaneous rise rate cannot be extrapolated indefinitely through the entire transient. || 假設井面積100m²、瞬時流入20及流出5m³/s，dz/dt=(20−5)/100=0.15m/s；流量差不假定長期固定。~Assume shaft area100m² with instantaneous inflow20 and outflow5m³/s. Rise ratedz/dt=0.15m/s does not assume that imbalance persists. || 將流入流出正方向畫在接點，核對井面積是否隨高程變化，並用短時間積分檢查水位增量。將算出的水位回饋到管路動量方程，不把指定流量差當成與井水位完全無關的邊界。~Draw flow signs at the junction, check whether shaft area changes with elevation and verify level increments by short-step integration. Feed the updated level back into conduit momentum rather than treating the imposed imbalance as independent of shaft water level. || 面積使用直徑代替會破壞量綱，井身變截面時固定面積又會誤估上升速度。只積分入流不扣下游流量，會虛增儲水並製造不存在的溢井預測。~Substituting diameter for area breaks dimensional consistency, while changing shaft sections invalidate a fixed-area rate. Integrating inflow without subtracting downstream flow invents storage and can predict a shaft overflow that the stated balance does not support. || 瞬時水位上升速度可直接乘任意長時間而不必更新管內流量。~An instantaneous shaft rise rate can be multiplied by any duration without updating conduit flow.
剛性水柱振盪週期~Rigid-column oscillation period || 較慢的井水位振盪可在特定條件下用剛性水柱近似，水柱慣性與自由水面重力形成回復系統。這與快速彈性波不同，忽略摩擦與壓縮性只為得到可核對的基準週期；實際控制器、節流口及變截面會改變衰減與穩定性。~Slower shaft-level oscillation can be approximated by a rigid water column under defined conditions, with column inertia and free-surface gravity forming a restoring system. This differs from the fast elastic wave. Neglecting friction and compressibility gives a checkable reference period, while controls, throttles and variable geometry change damping and stability in the actual installation. || 假設定水位上庫、均勻管L=1000m及Ap=10m²、井As=100m²，無摩擦小振幅且忽略井水慣性，T=2π√(LAs/gAp)=200.607s。~Assume fixed reservoir level, uniform conduitL=1000m,Ap=10m² and shaftAs=100m². Frictionless small oscillations neglecting shaft inertia haveT=200.607s. || 將管內剛性水柱動量與井內連續方程聯立，核對係數量綱為時間平方。以小擾動數值解比較解析週期，再逐步加入摩擦、井水慣性與控制器，標註每次加入機制後的週期及衰減差異。~Couple rigid-column momentum with shaft continuity and check that the period coefficient has time-squared units. Compare an analytical period with a small-disturbance numerical solution, then add friction, shaft inertia and controls separately, recording changes in period and damping. || 用此長週期代替壓力波往返時間會漏掉早期水錘，忽略機組控制又可能看不到自激振盪。模型沒有耗散時持續振動是其假設結果，不能當成實際阻尼證據。~Using this long period in place of wave travel time misses early water hammer, and omitted machine control can hide self-excitation. Persistent motion in a lossless model follows its assumptions and does not measure real-system damping. || 調壓井剛性水柱週期與管路彈性壓力波往返時間必定完全相同。~The rigid-column surge period must equal the conduit’s elastic-wave round-trip time.
理想湧升能量界限~Ideal upsurge energy estimate || 突然停止下游取水後，管內水柱動能可轉為井中水位上升的位能，提供無損理想基準。必須把井位移相對於固定水庫水面定義，並說明初始水位偏差；忽略摩擦、井水慣性與壓力彈性能量時，結果不能視為實際溢流高度的完整設計包絡。~After downstream demand stops, conduit kinetic energy can become potential energy in a rising shaft, giving a lossless reference. Define displacement relative to the fixed reservoir surface and specify the initial level offset. When friction, shaft inertia and elastic-wave energy are omitted, the estimate cannot serve as a complete design envelope for actual overflow height. || 假設初始井位等於固定庫位、L=1000m、Ap=10m²、As=100m²、V0=2m/s，瞬停下游且無損，zmax=V0√(LAp/gAs)=6.3855m。~Assume initial shaft level equals fixed reservoir level,L=1000m,Ap=10m²,As=100m²,V0=2m/s and instantaneous demand stop. Lossless rigid-columnzmax=6.3855m. || 寫出初始水柱動能與井水位能的等式，確認上庫可視為定水位且初始井位偏差為零。再用動量連續方程數值解對照，另測非零初始偏差、損失和彈性波對最高及最低水位的影響。~Write initial column kinetic energy and shaft potential energy, checking fixed reservoir level and zero initial shaft offset. Compare with coupled momentum-continuity integration, then separately test nonzero initial offset, loss and elastic-wave effects on both maximum and minimum levels. || 初始井水位若已因摩擦低於庫位，直接套零偏差公式會遺漏能量項。把無損湧升直接當允許井高也會忽略自由高、通氣與更複雜邊界造成的變化。~An initial shaft level depressed by friction requires an additional energy term. Treating the lossless rise as an allowable shaft height also omits freeboard, ventilation and changes caused by more complex boundaries. || 理想無損湧升數值就是任何真實調壓井所需的完整井高。~The ideal lossless rise directly gives the complete required height for every real surge shaft.
沿程摩擦與耗散~Distributed friction and dissipation || 管壁摩擦耗散能量並影響井水振盪衰減，穩態摩擦式可作第一層準穩態近似。反向流動時損失應反向抵抗速度，不能永遠沿固定坐標扣水頭；快速瞬態的非穩態摩擦則可能需要額外模型，不能只靠增大摩擦係數修正錯誤結果。~Wall friction dissipates energy and influences surge decay, with a steady relation serving as a first quasi-steady approximation. During flow reversal the loss must oppose velocity rather than remain fixed in one coordinate direction. Rapid transients may require unsteady friction, which should not be replaced by arbitrarily increasing a coefficient to compensate for an incorrect model. || 假設Darcy摩擦係數0.02、管長1000m、直徑2m、速率2m/s，hf=f(L/D)V²/(2g)=2.0387m，僅為此工況準穩態損失。~Assume Darcy factor0.02,length1000m,diameter2m and speed2m/s. Quasi-steady loss hf=f(L/D)V²/(2g)=2.0387m at this condition. || 註明使用Darcy而非Fanning係數，從粗糙度與雷諾數核對假設範圍。將摩擦寫成抵抗流向的V乘絕對V形式，檢查流向反轉時仍耗能，再比較不同摩擦模型對衰減歷時的影響。~Identify the Darcy rather than Fanning convention and check roughness and Reynolds assumptions. Express directional friction using velocity times its magnitude, verify dissipation during reversal and compare how alternative friction representations change the decay history. || 混淆兩種摩擦係數可造成四倍差異，流向反轉後符號不改更可能讓摩擦虛假供能。以強阻尼掩蓋時間步誤差，會讓看似平順的曲線失去物理可信度。~Confusing friction conventions introduces a factor-of-four error, and the wrong reversal sign can make friction supply energy. Artificial damping that hides time-step errors yields smooth-looking curves without reliable physical meaning. || 管路反向流動時摩擦仍應保持原方向並向水流提供能量。~During reversed flow friction keeps its original direction and supplies energy to the water.
節流孔與局部損失~Throttle opening and local loss || 節流可改變井與主管之間的交換及耗散，但更大阻力不保證所有壓力峰值都下降。孔口附近的局部低壓、流向切換和收縮係數需要另外檢查；準穩態孔流關係只描述指定瞬間的流量水頭差，不能直接取代完整調壓設施的瞬態模型。~A throttle changes exchange and dissipation between shaft and conduit, but increased resistance does not guarantee lower pressure peaks everywhere. Local suction, reversal and contraction behavior require separate checks. A quasi-steady orifice relation describes one flow-head condition and cannot replace a transient model of the complete surge arrangement and its connected waterway. || 假設孔口Q=10m³/s、Cd=0.65、有效面積2m²，水頭差h=(Q/CdA)²/(2g)=3.0159m；未驗局部空化。~Assume orifice flow10m³/s, coefficient0.65 and effective area2m². Head differenceh=(Q/CdA)²/(2g)=3.0159m, without evaluating local cavitation. || 核對係數對應的幾何與流向，標明有效孔面積而非整個井面積。比較入井與出井的壓差資料，將孔口關係接入動量及連續方程，再檢查最低絕對壓力與反向流條件而非只看耗能增加。~Check the coefficient’s geometry and direction and use opening area rather than full shaft area. Compare inward and outward pressure differences, couple the opening relation to momentum and continuity and inspect minimum absolute pressure and reversal rather than only increased dissipation. || 孔口太小可能限制快速交換而提高主管壓力，收縮區低壓也可能造成空化。直接用同一係數描述兩個方向，會漏掉非對稱構造引起的不同水頭損失。~An overly restrictive opening can hinder rapid exchange and raise conduit pressure, while a contracted jet can cavitate. Applying one coefficient to both directions misses asymmetric losses caused by the actual opening arrangement. || 節流孔越小就必定同時降低所有位置的最大與最小壓力風險。~A smaller throttle opening necessarily reduces every maximum- and minimum-pressure risk throughout the system.
絕對壓力與汽化~Absolute pressure and vapor formation || 負表壓不等於汽化，必須加上當地大氣壓後與相應溫度的蒸氣壓比較。即使某測點高於蒸氣壓，附近收縮區或未量到的瞬態仍可能更低；水柱分離涉及兩相或氣穴模型，不能把單相計算得到的不合理低壓照單全收。~Negative gauge pressure is not itself vapor formation; add local atmospheric pressure and compare against vapor pressure at the relevant temperature. A measured point above vapor pressure does not exclude lower local or unresolved transient values. Column separation requires appropriate cavity or multiphase treatment rather than accepting physically impossible pressures from a single-phase computation. || 假設大氣壓100kPa、表壓−80kPa、蒸氣壓2.34kPa，絕對壓20kPa，比蒸氣壓高17.66kPa；只代表該點該時刻。~Assume atmospheric100kPa,gauge−80kPa and vapor pressure2.34kPa. Absolute pressure20kPa exceeds vapor by17.66kPa only at that location and instant. || 確認壓力感測器為表壓或絕對型，記錄大氣壓與水溫並統一基準。沿整條管線檢查最低壓力歷時及高點，對低於蒸氣壓的單相結果改用適當模型，並保留未解析局部區域的限制。~Verify gauge versus absolute instrumentation, record atmospheric pressure and temperature and align references. Inspect minimum histories and high points along the full conduit, replace invalid single-phase predictions with suitable models and retain limitations for unresolved local regions. || 用海平面標準大氣壓代替高海拔實值會錯估餘量，稀疏取樣則可能漏掉短低壓。氣穴再閉合形成的壓力峰值也不會在只檢查原始高壓的流程中出現。~Using standard sea-level atmosphere at altitude misstates the margin, and sparse sampling can miss brief minima. Cavity rejoining can produce pressure peaks absent from a procedure that checks only the original high-pressure state. || 任何負表壓都立即代表汽化而正表壓則保證整條管線沒有空化。~Every negative gauge pressure means vaporization, while positive gauge pressure guarantees no cavitation anywhere.
特徵網格與收斂~Characteristic grid and convergence || 瞬態數值解需要把傳播速度、空間網格與時間步配合，否則波前可能被過度擴散或錯置。特徵線恰好落在網格點是便利條件，並不是邊界、摩擦或兩相處理都正確的證明；必須用可解析基準及細化比較檢查壓力峰值、到時和守恆。~Transient calculations coordinate wave speed, spatial grid and time step to avoid misplaced or excessively diffused fronts. Characteristics landing on grid points is convenient, not proof that boundaries, friction and cavities are handled correctly. Analytical benchmarks and refinement comparisons must check peak pressure, arrival time and conservation as separate aspects of numerical credibility. || 假設a=1000m/s、Δx=100m、Δt=0.10s，Courant數aΔt/Δx=1；只對此均勻網格特徵到點，不是完整精度證明。~Assumea=1000m/s,spacing100m and step0.10s. Courant number1 aligns characteristics on this uniform grid but does not prove full accuracy. || 先用單管首波及已知反射時序作基準，將空間與時間步一起細化並比較峰值和到達時間。對各支管核對波速與網格，檢查質量殘差及邊界更新順序，記錄收斂而非只呈現平滑曲線。~Benchmark first-wave amplitude and known reflection timing, refine space and time together and compare peaks and arrival. Check every branch’s celerity and grid, mass residual and boundary-update sequence, documenting convergence rather than merely presenting smooth plots. || 光滑曲線可能只是數值耗散抹掉了尖峰，Courant數正確也不能修復錯誤閥門邊界。若網格改變就讓峰值大幅移動，未收斂結果不應被包裝成確定的壓力包絡。~A smooth curve may reflect numerical damping that erased a peak, and correct Courant number cannot repair an incorrect valve boundary. Peaks that move materially under refinement indicate an unconverged result rather than a definitive pressure envelope. || Courant數等於一就能保證任何邊界、空化與摩擦模型都完全正確。~A Courant number of one guarantees that every boundary, cavitation and friction model is correct.
''')
META['b260']=dict(sources=['hydro-structures','coachella-surge','eklutna-history','coachella-project'],vendorSources=['hydro-structures','coachella-surge'],related=['b258','b259'],summary=pair('本課將快速彈性壓力波與較慢的調壓井自由水面振盪分開建模，再用共同邊界把兩者連起來。十個單元涵蓋波速、往返時間、首波增量、井內連續方程、剛性水柱週期、無損湧升、摩擦節流、汽化及數值收斂，所有算例都明定原創假設，不提供可直接套用的閥門動作規程。','This course models rapid elastic pressure waves separately from slower free-surface surge oscillations, then reconnects them through shared boundaries. Ten units cover celerity, travel time, first-wave increment, continuity, rigid-column period, ideal upsurge, friction, throttling, vapor formation and numerical convergence. All examples state original assumptions rather than prescribing transferable valve-operating procedures.'),history=pair('調壓設施的作用是改變長引水路的動量交換與壓力邊界，並非讓水錘從此消失。埃克盧特納官方歷史記錄調壓井於一九五三年開挖、一九五四年襯砌，提供真實井式設施的背景。科切拉配水管網則出現在墾務局一九五四年的湧浪控制專論，其灌溉配水邊界不應直接等同水力機組。工兵團二〇〇八年更新的水力電廠結構手冊提供另一方法入口。本課把各文件年代保留為出版或施工事實，所有管長、流速、井面積和壓力則另設為教學算例。','Surge facilities change momentum exchange and pressure boundaries in long waterways rather than eliminating every transient. Eklutna’s official history records shaft excavation in1953 and lining in1954 as a genuine shaft context. The Coachella distribution network appears in Reclamation’s1954 surge-control monograph, but irrigation boundaries are not equated with turbine behavior. USACE’s2008 hydroelectric structural update provides another methodological entry point. Dates remain publication or construction facts; conduit length, velocity, shaft area and pressure are separately specified as synthetic teaching inputs throughout the lesson.'),example=pair('原創井面積敏感度：定水位上庫、無損剛性水柱、初始井位與庫位相同，L=1000m、Ap=10m²、V0=2m/s且瞬停下游時，As=100m²得到zmax=6.3855m。將井面積增加10%至110m²而其他假設不變，湧升變為6.3855/√1.1≈6.0883m，降低約4.65%，並非10%。同時理想週期會乘√1.1而變長。學徒應比較較低湧升與較長振盪的不同效果，再加入摩擦、井水慣性、通氣及彈性管路，不把理想幅值減少誤稱所有壓力風險均以相同比例降低。','Original shaft-area sensitivity: assume a fixed reservoir, lossless rigid column, equal initial shaft and reservoir levels,L=1000m,Ap=10m²,V0=2m/s and instantaneous downstream demand stop. Shaft area100m² gives maximum rise6.3855m. Increasing area10% to110m² with all other assumptions fixed gives6.3855/√1.1≈6.0883m, about4.65% lower rather than10%. The ideal period simultaneously increases by√1.1. Apprentices compare lower rise with longer oscillation before adding friction, shaft inertia, ventilation and elastic waterways. A reduced ideal amplitude does not imply that every pressure risk declines by the same percentage across the full connected system.'),timeline=[('1953','埃克盧特納調壓井開始並完成開挖~Eklutna surge-tank excavation starts and reaches completion'),('1954','墾務局出版科切拉配水管網湧浪控制專論~Reclamation publishes Coachella distribution-system surge-control monograph'),('2008','工兵團更新水力電廠結構設計手冊~USACE updates hydroelectric power-plant structural design guidance')],codes=['工程專論第十七號科切拉配水管網湧浪控制~Engineering Monograph17 Surge Control on Coachella Distribution System','水力電廠結構規劃與設計EM1110-2-3001~EM1110-2-3001 hydroelectric structural planning and design'],landmarks=['埃克盧特納：調壓井實際配置背景~Eklutna: actual surge-shaft configuration context','科切拉配水管網：不同邊界湧浪比較~Coachella distribution system: contrasting surge boundaries'],place=dict(name='埃克盧特納公共調壓工程背景~Eklutna public surge-facility context',country='美國~United States',lat=61.467,lng=-149.150,query='Eklutna Hydroelectric Project Alaska'))
if __name__=='__main__':generate()
